// GENERATED by tools/build-walkthrough.js from the real Java source. Do not edit the code strings by hand.
const WALK=[{"file":"app/Main.java","sum":"<p><b>Main</b> is where the program starts. Java always looks for a method named <code>main</code> and runs it first. In our project Main is very small on purpose: it only creates the main pieces and starts the menu. All real work happens in other classes (this is the <b>Single Responsibility</b> idea: one class, one job).</p>","lines":30,"parts":[{"t":"Package, imports and class header","n":"<p><code>package app;</code> says this file belongs to the <b>app</b> folder (a package is a folder of related classes). Each <code>import</code> line lets us use a class from another package without typing its full path. <code>public class Main</code> starts the class. <code>public</code> means any other code may use it.</p>","a":1,"c":"package app;\n\nimport service.LibraryService;\nimport util.ConsoleHelper;\n\n/**\n * Starts the Library Management System. Main stays thin:\n * it only creates the main objects and hands control to the MenuController.\n *\n * Run it with: java -cp out app.Main\n * Optional: give another data folder, for example: java -cp out app.Main mydata\n */\npublic class Main {"},{"t":"The main method","n":"<p>Reading the header word by word: <code>public</code> = anyone can call it. <code>static</code> = it belongs to the class, so Java can run it without making a Main object first. <code>void</code> = it gives back nothing. <code>String[] args</code> = the words typed after the program name, such as a data folder.</p><p>Inside: the first line chooses the data folder. <code>(args.length &gt; 0) ? args[0] : \"data\"</code> is a short if-else: if the user typed something, use it, otherwise use <code>\"data\"</code>. <code>try ( ... )</code> is <b>try-with-resources</b>: the console is closed automatically when the block ends, even if an error happens. Then we create <code>LibraryService</code> (the rules), give it to <code>MenuController</code> (the screen), and call <code>menu.run()</code> to begin.</p>","a":15,"c":"    /**\n     * The program starts here.\n     *\n     * @param args optional: the name of the data folder (default is \"data\")\n     */\n    public static void main(String[] args) {\n        String dataFolder = (args.length > 0) ? args[0] : \"data\";\n\n        // try-with-resources: the ConsoleHelper (and its Scanner) is closed automatically at the end\n        try (ConsoleHelper console = new ConsoleHelper()) {\n            LibraryService service = new LibraryService(dataFolder);\n            MenuController menu = new MenuController(console, service);\n            menu.run();\n        }\n    }\n}"}]},{"file":"model/LibraryItem.java","sum":"<p><b>LibraryItem</b> is an <b>abstract class</b>: the parent of everything we can borrow. It keeps what every item shares: an ID, a title, and whether it is on the shelf. You cannot write <code>new LibraryItem(...)</code>; you create a <code>Book</code> or a <code>Magazine</code> instead.</p>","lines":76,"parts":[{"t":"Class header and fields","n":"<p><code>abstract</code> means “unfinished on purpose, only for being a parent”. The three fields are <code>private</code>, so other classes cannot change them directly (<b>encapsulation</b>). <code>final</code> on <code>itemId</code> means it is set once and can never change. <code>available</code> is a <code>boolean</code> (true or false): true = on the shelf, false = borrowed.</p>","a":1,"c":"package model;\n\n/**\n * ABSTRACT parent class of everything the library can lend (Book, Magazine).\n *\n * An abstract class cannot be created with \"new\". It only holds what all\n * items share: an ID, a title, and whether the item is on the shelf.\n * Each child class must fill in the abstract methods.\n */\npublic abstract class LibraryItem {\n\n    private final String itemId;  // final = can never change after it is set\n    private String title;\n    private boolean available;    // true = on the shelf, false = borrowed"},{"t":"Constructor","n":"<p>A <b>constructor</b> runs when an object is created and sets its starting values. It has the same name as the class and no return type. First it checks the ID is not null or blank (<code>||</code> means OR) and throws <code>IllegalArgumentException</code> if it is. <code>itemId.trim().toUpperCase()</code> removes extra spaces and makes capitals, so “b001” and “B001” become the same ID. <code>setTitle(title)</code> reuses the setter so the title is checked in one place (<b>DRY</b>: don’t repeat yourself). Every new item starts with <code>available = true</code>.</p>","a":16,"c":"    /**\n     * Creates an item. New items start as available.\n     *\n     * @param itemId the unique ID (saved in capital letters)\n     * @param title  the title (cannot be empty)\n     */\n    public LibraryItem(String itemId, String title) {\n        if (itemId == null || itemId.isBlank()) {\n            throw new IllegalArgumentException(\"Item ID cannot be empty.\");\n        }\n        this.itemId = itemId.trim().toUpperCase();\n        setTitle(title);\n        this.available = true;\n    }"},{"t":"Getters for ID and title","n":"<p>A <b>getter</b> lets other classes read a private field. <code>return itemId;</code> hands the value back. There is no setter for the ID because it must never change.</p>","a":31,"c":"    /** @return the item ID */\n    public String getItemId() {\n        return itemId;\n    }\n\n    /** @return the title */\n    public String getTitle() {\n        return title;\n    }"},{"t":"setTitle (with validation)","n":"<p>A <b>setter</b> changes a field, but only after checking the new value. If the title is null or blank, we throw an error and the old title stays. <code>this.title = title.trim()</code>: <code>this.title</code> is the object’s field, plain <code>title</code> is the parameter. Forgetting <code>this.</code> is a classic bug.</p>","a":41,"c":"    /**\n     * Changes the title. Empty titles are rejected.\n     *\n     * @param title the new title\n     */\n    public void setTitle(String title) {\n        if (title == null || title.isBlank()) {\n            throw new IllegalArgumentException(\"Title cannot be empty.\");\n        }\n        this.title = title.trim();\n    }"},{"t":"Availability methods","n":"<p><code>isAvailable()</code> tells if the item is on the shelf. <code>markBorrowed()</code> sets <code>available</code> to false. <code>markReturned()</code> sets it back to true. Other classes use these two methods instead of changing the field, which keeps control inside this class.</p>","a":53,"c":"    /** @return true if the item is on the shelf */\n    public boolean isAvailable() {\n        return available;\n    }\n\n    /** Marks the item as borrowed. */\n    public void markBorrowed() {\n        this.available = false;\n    }\n\n    /** Marks the item as back on the shelf. */\n    public void markReturned() {\n        this.available = true;\n    }"},{"t":"Abstract methods","n":"<p>An <b>abstract method</b> has a header but no body. Each child class <b>must</b> write its own version. Book says “Book”, Magazine says “Magazine”; <code>getDetails()</code> gives the extra text; <code>toFileLine()</code> makes the line saved in items.txt.</p>","a":68,"c":"    /** @return the kind of item, for example \"Book\" */\n    public abstract String getItemType();\n\n    /** @return a short description of the extra details of this item */\n    public abstract String getDetails();\n\n    /** @return this item as one line of text for the data file */\n    public abstract String toFileLine();\n}"}]},{"file":"model/Book.java","sum":"<p><b>Book</b> is a kind of LibraryItem (<code>extends</code> = “is a”). It gets the ID, title and availability from the parent, and adds an <b>author</b> and an <b>ISBN</b>.</p>","lines":67,"parts":[{"t":"Class header and fields","n":"<p><code>extends LibraryItem</code> means Book inherits everything public in LibraryItem. The two new private fields are only for books.</p>","a":1,"c":"package model;\n\n/**\n * A book. It IS-A LibraryItem (inheritance), and adds an author and an ISBN.\n */\npublic class Book extends LibraryItem {\n\n    private String author;\n    private String isbn;"},{"t":"Constructor with super","n":"<p><code>super(itemId, title)</code> calls the parent constructor, which stores the ID and title. It must be the <b>first line</b>. Then the child fills its own fields using its setters, so the author and ISBN get checked too.</p>","a":11,"c":"    /**\n     * @param itemId the unique ID\n     * @param title  the title\n     * @param author the author's name\n     * @param isbn   the ISBN number\n     */\n    public Book(String itemId, String title, String author, String isbn) {\n        super(itemId, title); // let LibraryItem set the ID and title\n        setAuthor(author);\n        setIsbn(isbn);\n    }"},{"t":"Author getter and setter","n":"<p>The setter rejects empty text, then saves the trimmed value. This is the same pattern as setTitle: private field, public getter, setter with a check.</p>","a":23,"c":"    /** @return the author */\n    public String getAuthor() {\n        return author;\n    }\n\n    /**\n     * @param author the new author (cannot be empty)\n     */\n    public void setAuthor(String author) {\n        if (author == null || author.isBlank()) {\n            throw new IllegalArgumentException(\"Author cannot be empty.\");\n        }\n        this.author = author.trim();\n    }"},{"t":"ISBN getter and setter","n":"<p>Same pattern. ISBN is stored as a String (not a number) because it can have leading zeros and we never do math with it.</p>","a":38,"c":"    /** @return the ISBN */\n    public String getIsbn() {\n        return isbn;\n    }\n\n    /**\n     * @param isbn the new ISBN (cannot be empty)\n     */\n    public void setIsbn(String isbn) {\n        if (isbn == null || isbn.isBlank()) {\n            throw new IllegalArgumentException(\"ISBN cannot be empty.\");\n        }\n        this.isbn = isbn.trim();\n    }"},{"t":"The three overrides","n":"<p><code>@Override</code> tells Java: “I am replacing a parent method.” If the name is misspelled, Java gives an error. <code>getItemType()</code> returns “Book”. <code>getDetails()</code> builds text like “by Robert C. Martin (ISBN 978…)”. <code>toFileLine()</code> joins the fields with <code>|</code> starting with BOOK, so the loader knows the type. This is <b>polymorphism</b>: the menu calls <code>item.getDetails()</code> and Java runs the Book version for a Book.</p>","a":53,"c":"    @Override\n    public String getItemType() {\n        return \"Book\";\n    }\n\n    @Override\n    public String getDetails() {\n        return \"by \" + author + \" (ISBN \" + isbn + \")\";\n    }\n\n    @Override\n    public String toFileLine() {\n        return \"BOOK|\" + getItemId() + \"|\" + getTitle() + \"|\" + author + \"|\" + isbn;\n    }\n}"}]},{"file":"model/Magazine.java","sum":"<p><b>Magazine</b> is the second kind of LibraryItem. It works exactly like Book, but has an <b>issue</b> (for example “Issue 12”) and a <b>publisher</b> instead of an author and ISBN.</p>","lines":67,"parts":[{"t":"Class header and fields","n":"<p>Same idea as Book: <code>extends LibraryItem</code>, plus two private fields.</p>","a":1,"c":"package model;\n\n/**\n * A magazine. It IS-A LibraryItem (inheritance), and adds an issue and a publisher.\n */\npublic class Magazine extends LibraryItem {\n\n    private String issue;\n    private String publisher;"},{"t":"Constructor","n":"<p>Calls <code>super(itemId, title)</code> first, then sets issue and publisher through the setters (which reject empty text).</p>","a":11,"c":"    /**\n     * @param itemId    the unique ID\n     * @param title     the title\n     * @param issue     the issue, for example \"Issue 12\" or \"March 2026\"\n     * @param publisher the company that publishes the magazine\n     */\n    public Magazine(String itemId, String title, String issue, String publisher) {\n        super(itemId, title);\n        setIssue(issue);\n        setPublisher(publisher);\n    }"},{"t":"Issue getter and setter","n":"<p>Getter returns the field. Setter validates, then trims and saves.</p>","a":23,"c":"    /** @return the issue */\n    public String getIssue() {\n        return issue;\n    }\n\n    /**\n     * @param issue the new issue (cannot be empty)\n     */\n    public void setIssue(String issue) {\n        if (issue == null || issue.isBlank()) {\n            throw new IllegalArgumentException(\"Issue cannot be empty.\");\n        }\n        this.issue = issue.trim();\n    }"},{"t":"Publisher getter and setter","n":"<p>Same pattern again.</p>","a":38,"c":"    /** @return the publisher */\n    public String getPublisher() {\n        return publisher;\n    }\n\n    /**\n     * @param publisher the new publisher (cannot be empty)\n     */\n    public void setPublisher(String publisher) {\n        if (publisher == null || publisher.isBlank()) {\n            throw new IllegalArgumentException(\"Publisher cannot be empty.\");\n        }\n        this.publisher = publisher.trim();\n    }"},{"t":"The three overrides","n":"<p>Returns “Magazine”, details like “Issue 12, Publisher”, and a file line starting with <code>MAGAZINE|</code>. Because Book and Magazine both fill in the same three methods, one <code>List&lt;LibraryItem&gt;</code> can hold both.</p>","a":53,"c":"    @Override\n    public String getItemType() {\n        return \"Magazine\";\n    }\n\n    @Override\n    public String getDetails() {\n        return issue + \", \" + publisher;\n    }\n\n    @Override\n    public String toFileLine() {\n        return \"MAGAZINE|\" + getItemId() + \"|\" + getTitle() + \"|\" + issue + \"|\" + publisher;\n    }\n}"}]},{"file":"model/BorrowingPolicy.java","sum":"<p><b>BorrowingPolicy</b> is an <b>interface</b>: a list of promises with no code. Any class that <code>implements</code> it must write all three methods. It is the <b>Strategy</b> in our Strategy pattern: one set of rules that can be swapped.</p>","lines":33,"parts":[{"t":"The whole interface","n":"<p>The methods have no body, just a semicolon. <code>getMaxItems()</code> = how many items at once. <code>getLoanDays()</code> = how many days until due. <code>calculateFine(int daysOverdue)</code> = money owed for days late. <b>Why an interface?</b> A Member only needs to know “I have some policy”, not which one. That lets us add a new policy later without changing Member.</p>","a":1,"c":"package model;\n\n/**\n * STRATEGY PATTERN: the \"strategy\" interface.\n *\n * A borrowing policy holds the rules that change from one kind of member to\n * another: how many items they may borrow, for how many days, and how much\n * the fine is. Each kind of member gets its own policy class\n * (see StudentPolicy and FacultyPolicy in the pattern package).\n *\n * This interface lives in the model package because the Member class is the\n * one that uses it.\n */\npublic interface BorrowingPolicy {\n\n    /**\n     * @return the most items a member may borrow at the same time\n     */\n    int getMaxItems();\n\n    /**\n     * @return how many days a member may keep an item\n     */\n    int getLoanDays();\n\n    /**\n     * Works out the fine for an item that is late.\n     *\n     * @param daysOverdue how many days late the item is (0 or less means not late)\n     * @return the fine in PHP (0.0 if the item is not late)\n     */\n    double calculateFine(int daysOverdue);\n}"}]},{"file":"model/Member.java","sum":"<p><b>Member</b> is the abstract parent of StudentMember and FacultyMember. It stores the ID, the name, and a <b>BorrowingPolicy</b>. A Member <i>has a</i> policy (<b>composition</b>) and a Member never decides the rules itself; it asks the policy.</p>","lines":78,"parts":[{"t":"Class header and fields","n":"<p>The field type is <code>BorrowingPolicy</code>, the <b>interface</b>, not StudentPolicy. So a Member can hold any policy. <code>final</code> means the policy is given once and never replaced.</p>","a":1,"c":"package model;\n\n/**\n * ABSTRACT parent class of all library members (StudentMember, FacultyMember).\n *\n * A member HAS-A BorrowingPolicy (composition). The member does not decide\n * the borrowing rules by itself. It asks its policy. This is the Strategy pattern.\n */\npublic abstract class Member {\n\n    private final String memberId;\n    private String name;\n    private final BorrowingPolicy policy; // the rules for this member (an interface)"},{"t":"Constructor","n":"<p>It receives the ID, name and policy. It rejects a blank ID and a null policy (a member without rules would crash later). Then it saves the ID in capitals, saves the policy, and uses <code>setName</code> to check the name.</p>","a":15,"c":"    /**\n     * @param memberId the unique ID (saved in capital letters)\n     * @param name     the member's name (cannot be empty)\n     * @param policy   the borrowing rules for this member\n     */\n    public Member(String memberId, String name, BorrowingPolicy policy) {\n        if (memberId == null || memberId.isBlank()) {\n            throw new IllegalArgumentException(\"Member ID cannot be empty.\");\n        }\n        if (policy == null) {\n            throw new IllegalArgumentException(\"A member must have a borrowing policy.\");\n        }\n        this.memberId = memberId.trim().toUpperCase();\n        this.policy = policy;\n        setName(name);\n    }"},{"t":"Getters for ID and name","n":"<p>Simple getters. <code>memberId</code> has no setter because an ID must not change.</p>","a":32,"c":"    /** @return the member ID */\n    public String getMemberId() {\n        return memberId;\n    }\n\n    /** @return the member's name */\n    public String getName() {\n        return name;\n    }"},{"t":"setName (with validation)","n":"<p>Rejects empty names, trims the text, and saves it in the field.</p>","a":42,"c":"    /**\n     * @param name the new name (cannot be empty)\n     */\n    public void setName(String name) {\n        if (name == null || name.isBlank()) {\n            throw new IllegalArgumentException(\"Name cannot be empty.\");\n        }\n        this.name = name.trim();\n    }"},{"t":"Methods that ask the policy","n":"<p>These three methods do not calculate anything. They pass the question to <code>policy</code> (<b>delegation</b>). So a student gets 3 items and PHP 5.00 per day, and a faculty gets 10 items and PHP 2.00, only because they hold different policy objects. A bug here, like writing <code>daysOverdue * 5.00</code> directly, would skip the Strategy pattern.</p>","a":52,"c":"    /** @return the most items this member may borrow at once (asks the policy) */\n    public int getMaxItems() {\n        return policy.getMaxItems();\n    }\n\n    /** @return the number of days this member may keep an item (asks the policy) */\n    public int getLoanDays() {\n        return policy.getLoanDays();\n    }\n\n    /**\n     * @param daysOverdue how many days late the item is\n     * @return the fine for this member (asks the policy)\n     */\n    public double calculateFine(int daysOverdue) {\n        return policy.calculateFine(daysOverdue);\n    }"},{"t":"Abstract methods","n":"<p>Each child must say its type (“Student” / “Faculty”), its extra info (course / department), and its file line.</p>","a":70,"c":"    /** @return the kind of member, for example \"Student\" */\n    public abstract String getMemberType();\n\n    /** @return the extra detail of this member (course or department) */\n    public abstract String getExtraInfo();\n\n    /** @return this member as one line of text for the data file */\n    public abstract String toFileLine();\n}"}]},{"file":"model/StudentMember.java","sum":"<p><b>StudentMember</b> is a Member who studies a <b>course</b> (like BSIT).</p>","lines":50,"parts":[{"t":"Class header and field","n":"<p><code>extends Member</code>. The extra field is the course.</p>","a":1,"c":"package model;\n\n/**\n * A student who borrows from the library. It IS-A Member, and adds a course.\n */\npublic class StudentMember extends Member {\n\n    private String course;"},{"t":"Constructor","n":"<p>It takes a policy as a parameter and passes it up with <code>super(memberId, name, policy)</code>. The class does not choose the policy itself; the <b>Factory</b> gives it a <code>StudentPolicy</code>. Then it sets the course.</p>","a":10,"c":"    /**\n     * @param memberId the unique ID\n     * @param name     the student's name\n     * @param course   the student's course, for example \"BSIT\"\n     * @param policy   the borrowing rules (the factory gives a StudentPolicy)\n     */\n    public StudentMember(String memberId, String name, String course, BorrowingPolicy policy) {\n        super(memberId, name, policy);\n        setCourse(course);\n    }"},{"t":"Course getter and setter","n":"<p>Read the course, or change it after the “cannot be empty” check.</p>","a":21,"c":"    /** @return the course */\n    public String getCourse() {\n        return course;\n    }\n\n    /**\n     * @param course the new course (cannot be empty)\n     */\n    public void setCourse(String course) {\n        if (course == null || course.isBlank()) {\n            throw new IllegalArgumentException(\"Course cannot be empty.\");\n        }\n        this.course = course.trim();\n    }"},{"t":"The three overrides","n":"<p>Type is “Student”. <code>getExtraInfo()</code> returns the course (shown in the member table). <code>toFileLine()</code> gives <code>STUDENT|ID|Name|Course</code>.</p>","a":36,"c":"    @Override\n    public String getMemberType() {\n        return \"Student\";\n    }\n\n    @Override\n    public String getExtraInfo() {\n        return course;\n    }\n\n    @Override\n    public String toFileLine() {\n        return \"STUDENT|\" + getMemberId() + \"|\" + getName() + \"|\" + course;\n    }\n}"}]},{"file":"model/FacultyMember.java","sum":"<p><b>FacultyMember</b> is a Member who works in a <b>department</b>. It is the same design as StudentMember, with different extra data.</p>","lines":50,"parts":[{"t":"Class header and field","n":"<p><code>extends Member</code> with a <code>department</code> field.</p>","a":1,"c":"package model;\n\n/**\n * A teacher who borrows from the library. It IS-A Member, and adds a department.\n */\npublic class FacultyMember extends Member {\n\n    private String department;"},{"t":"Constructor","n":"<p>Passes ID, name and policy to the parent with <code>super(...)</code>, then sets the department.</p>","a":10,"c":"    /**\n     * @param memberId   the unique ID\n     * @param name       the teacher's name\n     * @param department the teacher's department, for example \"Computer Science\"\n     * @param policy     the borrowing rules (the factory gives a FacultyPolicy)\n     */\n    public FacultyMember(String memberId, String name, String department, BorrowingPolicy policy) {\n        super(memberId, name, policy);\n        setDepartment(department);\n    }"},{"t":"Department getter and setter","n":"<p>Same pattern as the course in StudentMember: read it, or change it after checking it is not empty.</p>","a":21,"c":"    /** @return the department */\n    public String getDepartment() {\n        return department;\n    }\n\n    /**\n     * @param department the new department (cannot be empty)\n     */\n    public void setDepartment(String department) {\n        if (department == null || department.isBlank()) {\n            throw new IllegalArgumentException(\"Department cannot be empty.\");\n        }\n        this.department = department.trim();\n    }"},{"t":"The three overrides","n":"<p>Type is “Faculty”, extra info is the department, and the file line starts with <code>FACULTY|</code>. Because StudentMember and FacultyMember both extend Member, code can treat both as a Member (<b>polymorphism</b>).</p>","a":36,"c":"    @Override\n    public String getMemberType() {\n        return \"Faculty\";\n    }\n\n    @Override\n    public String getExtraInfo() {\n        return department;\n    }\n\n    @Override\n    public String toFileLine() {\n        return \"FACULTY|\" + getMemberId() + \"|\" + getName() + \"|\" + department;\n    }\n}"}]},{"file":"model/Staff.java","sum":"<p><b>Staff</b> is a library worker who handles loans. It is a simple class with no parent. It shows the basic class pattern: private fields, a constructor, getters, validated setters, and save/load methods.</p>","lines":83,"parts":[{"t":"Class header and fields","n":"<p>The ID cannot change (<code>final</code>). Name and role can.</p>","a":1,"c":"package model;\n\n/**\n * A library staff member (librarian). Staff handle the borrowing at the desk.\n *\n * Staff is NOT a kind of Member, because staff do not borrow here,\n * so it is its own class.\n */\npublic class Staff {\n\n    private final String staffId;\n    private String name;\n    private String role;"},{"t":"Constructor","n":"<p>Checks the ID, saves it in capitals, then uses the setters for name and role so they are validated.</p>","a":15,"c":"    /**\n     * @param staffId the unique ID (saved in capital letters)\n     * @param name    the staff member's name\n     * @param role    the job, for example \"Head Librarian\"\n     */\n    public Staff(String staffId, String name, String role) {\n        if (staffId == null || staffId.isBlank()) {\n            throw new IllegalArgumentException(\"Staff ID cannot be empty.\");\n        }\n        this.staffId = staffId.trim().toUpperCase();\n        setName(name);\n        setRole(role);\n    }"},{"t":"Getters for ID and name","n":"<p>Return the private fields.</p>","a":29,"c":"    /** @return the staff ID */\n    public String getStaffId() {\n        return staffId;\n    }\n\n    /** @return the name */\n    public String getName() {\n        return name;\n    }"},{"t":"setName","n":"<p>Blank names are rejected; otherwise the trimmed name is saved.</p>","a":39,"c":"    /**\n     * @param name the new name (cannot be empty)\n     */\n    public void setName(String name) {\n        if (name == null || name.isBlank()) {\n            throw new IllegalArgumentException(\"Name cannot be empty.\");\n        }\n        this.name = name.trim();\n    }"},{"t":"getRole and setRole","n":"<p>Same pattern for the role.</p>","a":49,"c":"    /** @return the role */\n    public String getRole() {\n        return role;\n    }\n\n    /**\n     * @param role the new role (cannot be empty)\n     */\n    public void setRole(String role) {\n        if (role == null || role.isBlank()) {\n            throw new IllegalArgumentException(\"Role cannot be empty.\");\n        }\n        this.role = role.trim();\n    }"},{"t":"toFileLine","n":"<p>Joins the three fields with <code>|</code> to make one line such as <code>ST001|Maria Santos|Head Librarian</code>. Used when saving.</p>","a":64,"c":"    /** @return this staff member as one line of text for the data file */\n    public String toFileLine() {\n        return staffId + \"|\" + name + \"|\" + role;\n    }"},{"t":"fromFileLine","n":"<p><code>static</code> = called on the class: <code>Staff.fromFileLine(line)</code>. <code>line.split(\"\\\\|\", -1)</code> cuts the line at each <code>|</code> (the double backslash is needed because | is a special symbol). The <code>-1</code> keeps empty fields at the end. The line must have exactly 3 parts, otherwise we throw an error that the loader catches and reports as a skipped line. Then we build a new Staff.</p>","a":69,"c":"    /**\n     * Builds a Staff object from one line of the data file.\n     *\n     * @param line text like \"ST001|Maria Santos|Head Librarian\"\n     * @return the Staff object\n     * @throws IllegalArgumentException if the line is not in the correct format\n     */\n    public static Staff fromFileLine(String line) {\n        String[] parts = line.split(\"\\\\|\", -1); // -1 keeps empty fields at the end\n        if (parts.length != 3) {\n            throw new IllegalArgumentException(\"Staff line must have 3 fields but has \" + parts.length + \".\");\n        }\n        return new Staff(parts[0], parts[1], parts[2]);\n    }\n}"}]},{"file":"model/Loan.java","sum":"<p><b>Loan</b> remembers one borrowing: which item, which member, which staff, the dates, and any fine. It holds only data and date rules. It does not know about policies; the service does the fine math.</p>","lines":213,"parts":[{"t":"Imports, class and fields","n":"<p><code>LocalDate</code> is Java’s date type. <code>ChronoUnit</code> counts days between dates. The IDs and the borrow and due dates are <code>final</code> (they never change). <code>returnDate</code> is null until the item comes back; null means “not returned yet”. <code>fineAmount</code> is in PHP; <code>finePaid</code> tells if it was paid.</p>","a":1,"c":"package model;\n\nimport java.time.LocalDate;\nimport java.time.format.DateTimeParseException;\nimport java.time.temporal.ChronoUnit;\n\n/**\n * One borrowing record: who borrowed what, when, and when it is due.\n *\n * A loan stores IDs (text) instead of whole Book and Member objects.\n * This keeps saving to a file simple. To get the real Book or Member,\n * the service looks the ID up.\n *\n * The loan also keeps the fine, if the item was returned late.\n */\npublic class Loan {\n\n    private final String loanId;\n    private final String itemId;\n    private final String memberId;\n    private final String staffId;\n    private final LocalDate borrowDate;\n    private final LocalDate dueDate;\n    private LocalDate returnDate; // null means \"not returned yet\"\n    private double fineAmount;    // in PHP, 0 means no fine\n    private boolean finePaid;"},{"t":"Short constructor (new loan)","n":"<p>For a brand new loan we only know the IDs and dates. <code>this(...)</code> calls the other constructor, filling in “not returned”, fine 0.0 and not paid. <b>Overloading</b> means two constructors with the same name but different parameters.</p>","a":28,"c":"    /**\n     * Creates a NEW loan (not returned, no fine).\n     */\n    public Loan(String loanId, String itemId, String memberId, String staffId,\n                LocalDate borrowDate, LocalDate dueDate) {\n        this(loanId, itemId, memberId, staffId, borrowDate, dueDate, null, 0.0, false);\n    }"},{"t":"Full constructor (with all checks)","n":"<p>Used when loading from a file. It rejects: missing IDs, missing dates, a due date before the borrow date, a return date before the borrow date, and a negative fine. Then it saves everything (IDs in capitals). This is where bad file data gets stopped.</p>","a":36,"c":"    /**\n     * Creates a loan with every value. Used when loading from the data file.\n     *\n     * @throws IllegalArgumentException if any value is not valid\n     */\n    public Loan(String loanId, String itemId, String memberId, String staffId,\n                LocalDate borrowDate, LocalDate dueDate,\n                LocalDate returnDate, double fineAmount, boolean finePaid) {\n        if (isEmpty(loanId) || isEmpty(itemId) || isEmpty(memberId) || isEmpty(staffId)) {\n            throw new IllegalArgumentException(\"A loan needs a loan ID, item ID, member ID and staff ID.\");\n        }\n        if (borrowDate == null || dueDate == null) {\n            throw new IllegalArgumentException(\"A loan needs a borrow date and a due date.\");\n        }\n        if (dueDate.isBefore(borrowDate)) {\n            throw new IllegalArgumentException(\"The due date cannot be before the borrow date.\");\n        }\n        if (returnDate != null && returnDate.isBefore(borrowDate)) {\n            throw new IllegalArgumentException(\"The return date cannot be before the borrow date.\");\n        }\n        if (fineAmount < 0) {\n            throw new IllegalArgumentException(\"The fine cannot be negative.\");\n        }\n        this.loanId = loanId.trim().toUpperCase();\n        this.itemId = itemId.trim().toUpperCase();\n        this.memberId = memberId.trim().toUpperCase();\n        this.staffId = staffId.trim().toUpperCase();\n        this.borrowDate = borrowDate;\n        this.dueDate = dueDate;\n        this.returnDate = returnDate;\n        this.fineAmount = fineAmount;\n        this.finePaid = finePaid;\n    }"},{"t":"isEmpty helper","n":"<p>A small private method that says if a text is null or blank. It is used four times above, so we wrote it once (DRY).</p>","a":70,"c":"    /** Small helper: true if the text is null or only spaces. */\n    private static boolean isEmpty(String text) {\n        return text == null || text.isBlank();\n    }"},{"t":"Getters","n":"<p>One getter for each field so other classes can read them.</p>","a":75,"c":"    /** @return the loan ID */\n    public String getLoanId() {\n        return loanId;\n    }\n\n    /** @return the ID of the borrowed item */\n    public String getItemId() {\n        return itemId;\n    }\n\n    /** @return the ID of the member who borrowed it */\n    public String getMemberId() {\n        return memberId;\n    }\n\n    /** @return the ID of the staff member who handled the loan */\n    public String getStaffId() {\n        return staffId;\n    }\n\n    /** @return the date the item was borrowed */\n    public LocalDate getBorrowDate() {\n        return borrowDate;\n    }\n\n    /** @return the date the item must be back */\n    public LocalDate getDueDate() {\n        return dueDate;\n    }\n\n    /** @return the date the item came back, or null if it is still out */\n    public LocalDate getReturnDate() {\n        return returnDate;\n    }\n\n    /** @return the fine in PHP (0 if none) */\n    public double getFineAmount() {\n        return fineAmount;\n    }\n\n    /** @return true if the fine has been paid */\n    public boolean isFinePaid() {\n        return finePaid;\n    }"},{"t":"isReturned and hasFine","n":"<p><code>isReturned()</code> is true when <code>returnDate</code> is not null. <code>hasFine()</code> is true when the fine is more than zero.</p>","a":120,"c":"    /** @return true if the item has been returned */\n    public boolean isReturned() {\n        return returnDate != null;\n    }\n\n    /** @return true if this loan has a fine bigger than zero */\n    public boolean hasFine() {\n        return fineAmount > 0;\n    }"},{"t":"isOverdue","n":"<p>A loan is overdue only if it is <b>not returned</b> (<code>!</code> means NOT) <b>and</b> (<code>&amp;&amp;</code>) today is <b>after</b> the due date. Returning on the due date is not late.</p>","a":130,"c":"    /**\n     * A loan is overdue when it is NOT returned and today is after the due date.\n     *\n     * @param today the date to check against\n     * @return true if the loan is overdue\n     */\n    public boolean isOverdue(LocalDate today) {\n        return !isReturned() && today.isAfter(dueDate);\n    }"},{"t":"getDaysOverdue","n":"<p>If returned, count until the return date; if not, count until today (<code>? :</code> is a short if-else). <code>ChronoUnit.DAYS.between(dueDate, endDate)</code> is positive when the end is later than the due date. If the result is zero or less we give 0. <code>(int) days</code> changes the big <code>long</code> number to an <code>int</code>.</p>","a":140,"c":"    /**\n     * Counts how many days late the item is (or was).\n     * If the item is returned, it counts up to the return date.\n     * If it is still out, it counts up to today.\n     *\n     * @param today the date to use when the item is still out\n     * @return the number of days late (0 if not late)\n     */\n    public int getDaysOverdue(LocalDate today) {\n        LocalDate endDate = isReturned() ? returnDate : today;\n        long days = ChronoUnit.DAYS.between(dueDate, endDate);\n        return days > 0 ? (int) days : 0; // (int) turns the long number into an int\n    }"},{"t":"markReturned","n":"<p>Closes the loan. It refuses if the loan is already returned (<code>IllegalStateException</code>), if the date is missing or before the borrow date, or if the fine is negative. Then it saves the return date and the fine, and sets <code>finePaid</code> to false.</p>","a":154,"c":"    /**\n     * Closes the loan.\n     *\n     * @param date the return date\n     * @param fine the fine to charge (0 if the item is not late)\n     */\n    public void markReturned(LocalDate date, double fine) {\n        if (isReturned()) {\n            throw new IllegalStateException(\"This loan is already returned.\");\n        }\n        if (date == null || date.isBefore(borrowDate)) {\n            throw new IllegalArgumentException(\"The return date is not valid.\");\n        }\n        if (fine < 0) {\n            throw new IllegalArgumentException(\"The fine cannot be negative.\");\n        }\n        this.returnDate = date;\n        this.fineAmount = fine;\n        this.finePaid = false;\n    }"},{"t":"markFinePaid","n":"<p>Sets <code>finePaid</code> to true.</p>","a":175,"c":"    /** Marks the fine as paid. */\n    public void markFinePaid() {\n        this.finePaid = true;\n    }"},{"t":"toFileLine","n":"<p>Joins the 9 fields with <code>|</code>. If there is no return date, we write empty text so the field stays in place (that is why you see <code>||</code> in loans.txt).</p>","a":180,"c":"    /** @return this loan as one line of text for the data file */\n    public String toFileLine() {\n        String returnText = (returnDate == null) ? \"\" : returnDate.toString();\n        return loanId + \"|\" + itemId + \"|\" + memberId + \"|\" + staffId + \"|\"\n                + borrowDate + \"|\" + dueDate + \"|\" + returnText + \"|\"\n                + fineAmount + \"|\" + finePaid;\n    }"},{"t":"fromFileLine","n":"<p>Splits a line into 9 parts (error if not 9). <code>LocalDate.parse</code> reads dates written as YYYY-MM-DD; an empty return date means null. <code>Double.parseDouble</code> and <code>Boolean.parseBoolean</code> read the fine and the paid flag. The two <code>catch</code> blocks turn date or number mistakes into clear messages, so a bad line gets skipped instead of crashing the program.</p>","a":188,"c":"    /**\n     * Builds a Loan from one line of the data file.\n     *\n     * @param line text with 9 fields separated by \"|\"\n     * @return the Loan object\n     * @throws IllegalArgumentException if the line is not in the correct format\n     */\n    public static Loan fromFileLine(String line) {\n        String[] p = line.split(\"\\\\|\", -1);\n        if (p.length != 9) {\n            throw new IllegalArgumentException(\"Loan line must have 9 fields but has \" + p.length + \".\");\n        }\n        try {\n            LocalDate borrowDate = LocalDate.parse(p[4]);\n            LocalDate dueDate = LocalDate.parse(p[5]);\n            LocalDate returnDate = p[6].isBlank() ? null : LocalDate.parse(p[6]);\n            double fine = Double.parseDouble(p[7]);\n            boolean paid = Boolean.parseBoolean(p[8]);\n            return new Loan(p[0], p[1], p[2], p[3], borrowDate, dueDate, returnDate, fine, paid);\n        } catch (DateTimeParseException e) {\n            throw new IllegalArgumentException(\"A date is not in the format YYYY-MM-DD.\");\n        } catch (NumberFormatException e) {\n            throw new IllegalArgumentException(\"The fine is not a valid number.\");\n        }\n    }\n}"}]},{"file":"pattern/StudentPolicy.java","sum":"<p><b>StudentPolicy</b> is one <b>Strategy</b>: the rules for students.</p>","lines":32,"parts":[{"t":"Class header and constants","n":"<p><code>implements BorrowingPolicy</code> promises to write the three interface methods. <code>static final</code> makes a <b>constant</b>: one value for the whole program that never changes. Students: 3 items, 7 days, PHP 5.00 per day. Using named constants instead of loose numbers is clearer and easy to change in one place.</p>","a":1,"c":"package pattern;\n\nimport model.BorrowingPolicy;\n\n/**\n * STRATEGY PATTERN: the rules for students.\n * 3 items, 7 days, fine of PHP 5.00 for each day late.\n */\npublic class StudentPolicy implements BorrowingPolicy {\n\n    private static final int MAX_ITEMS = 3;          // static final = a constant that never changes\n    private static final int LOAN_DAYS = 7;\n    private static final double FINE_PER_DAY = 5.00; // PHP"},{"t":"getMaxItems and getLoanDays","n":"<p>Return the constants.</p>","a":15,"c":"    @Override\n    public int getMaxItems() {\n        return MAX_ITEMS;\n    }\n\n    @Override\n    public int getLoanDays() {\n        return LOAN_DAYS;\n    }"},{"t":"calculateFine","n":"<p>If the days overdue are zero or less, no fine. Otherwise days × PHP 5.00. Example: 12 days late = 60.0.</p>","a":25,"c":"    @Override\n    public double calculateFine(int daysOverdue) {\n        if (daysOverdue <= 0) {\n            return 0.0; // not late, so no fine\n        }\n        return daysOverdue * FINE_PER_DAY;\n    }\n}"}]},{"file":"pattern/FacultyPolicy.java","sum":"<p><b>FacultyPolicy</b> is the second Strategy. It is the same shape as StudentPolicy with different numbers.</p>","lines":32,"parts":[{"t":"Class header and constants","n":"<p>Faculty: 10 items, 30 days, PHP 2.00 per day.</p>","a":1,"c":"package pattern;\n\nimport model.BorrowingPolicy;\n\n/**\n * STRATEGY PATTERN: the rules for faculty (teachers).\n * 10 items, 30 days, fine of PHP 2.00 for each day late.\n */\npublic class FacultyPolicy implements BorrowingPolicy {\n\n    private static final int MAX_ITEMS = 10;\n    private static final int LOAN_DAYS = 30;\n    private static final double FINE_PER_DAY = 2.00; // PHP"},{"t":"getMaxItems and getLoanDays","n":"<p>Return the constants.</p>","a":15,"c":"    @Override\n    public int getMaxItems() {\n        return MAX_ITEMS;\n    }\n\n    @Override\n    public int getLoanDays() {\n        return LOAN_DAYS;\n    }"},{"t":"calculateFine","n":"<p>No fine if not late. Otherwise days × 2.00. To add a new member type (like Guest), you add one new policy class like this one and one case in the Factory.</p>","a":25,"c":"    @Override\n    public double calculateFine(int daysOverdue) {\n        if (daysOverdue <= 0) {\n            return 0.0;\n        }\n        return daysOverdue * FINE_PER_DAY;\n    }\n}"}]},{"file":"pattern/LibraryFactory.java","sum":"<p><b>LibraryFactory</b> is the <b>Factory pattern</b>. You give it a word such as “STUDENT” and it builds the right object. The rest of the program does not need to know which class to create.</p>","lines":101,"parts":[{"t":"Imports, class and private constructor","n":"<p>The constructor is <code>private</code>, so nobody can write <code>new LibraryFactory()</code>. All methods are <code>static</code>, so we call them on the class itself.</p>","a":1,"c":"package pattern;\n\nimport model.Book;\nimport model.FacultyMember;\nimport model.LibraryItem;\nimport model.Magazine;\nimport model.Member;\nimport model.StudentMember;\n\n/**\n * FACTORY PATTERN: the only place in the program that says \"new Book\",\n * \"new Magazine\", \"new StudentMember\" or \"new FacultyMember\".\n *\n * The menu and the file loader both ask this class for an object. They give a\n * type word like \"BOOK\" and get back a LibraryItem. They never need to know\n * which child class was created. This class also gives each member the right\n * BorrowingPolicy (Strategy pattern).\n *\n * All methods are static, so we call them like LibraryFactory.createItem(...)\n * without creating a LibraryFactory object.\n */\npublic class LibraryFactory {\n\n    /** Private constructor: nobody should create a LibraryFactory object. */\n    private LibraryFactory() {\n    }"},{"t":"createItem","n":"<p>The <code>switch</code> compares the type text (made capital and trimmed) with each <code>case</code>. “BOOK” makes a Book (detail1 = author, detail2 = ISBN). “MAGAZINE” makes a Magazine (issue, publisher). Anything else throws an error. The method returns <code>LibraryItem</code>, the parent, so callers can treat both the same way.</p>","a":28,"c":"    /**\n     * Creates a Book or a Magazine.\n     *\n     * @param type    \"BOOK\" or \"MAGAZINE\" (capital letters do not matter)\n     * @param id      the item ID\n     * @param title   the title\n     * @param detail1 the author (for a book) or the issue (for a magazine)\n     * @param detail2 the ISBN (for a book) or the publisher (for a magazine)\n     * @return the new item\n     * @throws IllegalArgumentException if the type is unknown or a value is not valid\n     */\n    public static LibraryItem createItem(String type, String id, String title,\n                                         String detail1, String detail2) {\n        switch (type.trim().toUpperCase()) {\n            case \"BOOK\":\n                return new Book(id, title, detail1, detail2);\n            case \"MAGAZINE\":\n                return new Magazine(id, title, detail1, detail2);\n            default:\n                throw new IllegalArgumentException(\"Unknown item type: \" + type);\n        }\n    }"},{"t":"createMember","n":"<p>Same idea for members. This is also where each member gets the <b>correct policy</b>: students get <code>new StudentPolicy()</code>, faculty get <code>new FacultyPolicy()</code>. Using the wrong policy here would give wrong limits and fines to every student.</p>","a":51,"c":"    /**\n     * Creates a StudentMember or a FacultyMember with the correct policy.\n     *\n     * @param type   \"STUDENT\" or \"FACULTY\"\n     * @param id     the member ID\n     * @param name   the member's name\n     * @param detail the course (student) or the department (faculty)\n     * @return the new member\n     * @throws IllegalArgumentException if the type is unknown or a value is not valid\n     */\n    public static Member createMember(String type, String id, String name, String detail) {\n        switch (type.trim().toUpperCase()) {\n            case \"STUDENT\":\n                return new StudentMember(id, name, detail, new StudentPolicy());\n            case \"FACULTY\":\n                return new FacultyMember(id, name, detail, new FacultyPolicy());\n            default:\n                throw new IllegalArgumentException(\"Unknown member type: \" + type);\n        }\n    }"},{"t":"createItemFromLine","n":"<p>Used when loading items.txt. It splits a saved line at <code>|</code>, checks there are exactly 5 parts, then calls <code>createItem</code> with them.</p>","a":72,"c":"    /**\n     * Builds an item from one line of the items data file.\n     *\n     * @param line text like \"BOOK|B001|Clean Code|Robert Martin|9780132350884\"\n     * @return the item\n     * @throws IllegalArgumentException if the line is not in the correct format\n     */\n    public static LibraryItem createItemFromLine(String line) {\n        String[] parts = line.split(\"\\\\|\", -1);\n        if (parts.length != 5) {\n            throw new IllegalArgumentException(\"Item line must have 5 fields but has \" + parts.length + \".\");\n        }\n        return createItem(parts[0], parts[1], parts[2], parts[3], parts[4]);\n    }"},{"t":"createMemberFromLine","n":"<p>Same for members.txt: 4 parts, then <code>createMember</code>. Because both the menu and the file loader use the same factory, the creation logic exists only once.</p>","a":87,"c":"    /**\n     * Builds a member from one line of the members data file.\n     *\n     * @param line text like \"STUDENT|S001|Ana Cruz|BSIT\"\n     * @return the member\n     * @throws IllegalArgumentException if the line is not in the correct format\n     */\n    public static Member createMemberFromLine(String line) {\n        String[] parts = line.split(\"\\\\|\", -1);\n        if (parts.length != 4) {\n            throw new IllegalArgumentException(\"Member line must have 4 fields but has \" + parts.length + \".\");\n        }\n        return createMember(parts[0], parts[1], parts[2], parts[3]);\n    }\n}"}]},{"file":"pattern/OverdueObserver.java","sum":"<p><b>OverdueObserver</b> is the <b>Observer</b> interface: anyone who wants overdue notices implements it.</p>","lines":22,"parts":[{"t":"The whole interface","n":"<p>One method: <code>onOverdueNotice(String message)</code>. LibraryService only knows this interface, not what the listeners do. In MenuController two small lambdas act as observers: one prints the notice, one saves it for menu option 9.</p>","a":1,"c":"package pattern;\n\n/**\n * OBSERVER PATTERN: the \"observer\" interface.\n *\n * Anything that wants to hear about overdue items implements this interface.\n * The LibraryService (the \"subject\") keeps a list of observers and calls\n * onOverdueNotice(...) on each one when something is overdue. The service\n * never knows what the observers do with the message.\n *\n * Because this interface has only one method, we can write an observer as a\n * short lambda, for example: message -> System.out.println(message)\n */\npublic interface OverdueObserver {\n\n    /**\n     * Called by the service when there is an overdue notice.\n     *\n     * @param message the text of the notice\n     */\n    void onOverdueNotice(String message);\n}"}]},{"file":"exception/LibraryException.java","sum":"<p><b>LibraryException</b> is the parent of all our own “library problem” errors.</p>","lines":20,"parts":[{"t":"The whole class","n":"<p><code>extends Exception</code> makes it a <b>checked</b> exception: Java forces us to catch it or declare it with <code>throws</code>. The constructor passes the message up with <code>super(message)</code>, so <code>e.getMessage()</code> works later. Having one parent lets MenuController catch every library problem with a single <code>catch (LibraryException e)</code>.</p>","a":1,"c":"package exception;\n\n/**\n * The parent of all our own exceptions.\n *\n * It extends Exception, so it is a \"checked\" exception. Java forces us to\n * either catch it or declare it with \"throws\". Because all our exceptions\n * share this parent, the menu can catch them all with one catch block.\n */\npublic class LibraryException extends Exception {\n\n    /**\n     * Creates the exception with a message that is safe to show to the user.\n     *\n     * @param message the explanation of what went wrong\n     */\n    public LibraryException(String message) {\n        super(message); // pass the message up to the Exception class\n    }\n}"}]},{"file":"exception/RecordNotFoundException.java","sum":"<p>Thrown when an ID does not exist (for example borrowing with a wrong member ID).</p>","lines":15,"parts":[{"t":"The whole class","n":"<p>It extends LibraryException and only passes the message up. It exists so the type of error is clear from its name. The Repository throws it in <code>getById</code>.</p>","a":1,"c":"package exception;\n\n/**\n * Thrown when we look for a record by its ID but it does not exist.\n * It is also used when something cannot be returned because it was never borrowed.\n */\npublic class RecordNotFoundException extends LibraryException {\n\n    /**\n     * @param message the explanation, for example \"Member ID 'S999' was not found.\"\n     */\n    public RecordNotFoundException(String message) {\n        super(message);\n    }\n}"}]},{"file":"exception/DuplicateRecordException.java","sum":"<p>Thrown when we try to add a record whose ID is already used.</p>","lines":15,"parts":[{"t":"The whole class","n":"<p>Same shape. The Repository throws it in <code>add</code> when the HashMap already has that ID.</p>","a":1,"c":"package exception;\n\n/**\n * Thrown when we try to add a record (item, member, staff, loan)\n * whose ID is already used by another record.\n */\npublic class DuplicateRecordException extends LibraryException {\n\n    /**\n     * @param message the explanation, for example \"Item ID 'B001' already exists.\"\n     */\n    public DuplicateRecordException(String message) {\n        super(message);\n    }\n}"}]},{"file":"exception/ItemNotAvailableException.java","sum":"<p>Thrown when an item cannot be borrowed or removed because of its state.</p>","lines":15,"parts":[{"t":"The whole class","n":"<p>LibraryService throws it when you borrow an item that is already borrowed, or remove an item that has loan records.</p>","a":1,"c":"package exception;\n\n/**\n * Thrown when someone tries to borrow an item that is already borrowed,\n * or tries to remove an item that still has loan records.\n */\npublic class ItemNotAvailableException extends LibraryException {\n\n    /**\n     * @param message the explanation, for example \"'Clean Code' is already borrowed.\"\n     */\n    public ItemNotAvailableException(String message) {\n        super(message);\n    }\n}"}]},{"file":"exception/BorrowingLimitExceededException.java","sum":"<p>Thrown when a member already has the most items allowed.</p>","lines":26,"parts":[{"t":"The whole class","n":"<p>This one stores extra data: the <code>limit</code>, in a private field with a getter. The constructor needs <b>two</b> values: the message and the limit. Forgetting the second one is a compile error.</p>","a":1,"c":"package exception;\n\n/**\n * Thrown when a member already has the maximum number of borrowed items.\n * It also remembers the limit number, so other code can read it with getLimit().\n */\npublic class BorrowingLimitExceededException extends LibraryException {\n\n    private final int limit; // the most items this member may borrow\n\n    /**\n     * @param message the explanation to show to the user\n     * @param limit   the borrowing limit that was reached\n     */\n    public BorrowingLimitExceededException(String message, int limit) {\n        super(message);\n        this.limit = limit;\n    }\n\n    /**\n     * @return the borrowing limit that was reached\n     */\n    public int getLimit() {\n        return limit;\n    }\n}"}]},{"file":"storage/Repository.java","sum":"<p><b>Repository&lt;T&gt;</b> is a <b>generic class</b> we wrote. It stores records of any type <code>T</code> and does saving and loading. We make four: for items, members, staff and loans. It uses two collections: an <b>ArrayList</b> (ordered list) and a <b>HashMap</b> (fast lookup by ID).</p>","lines":203,"parts":[{"t":"Imports","n":"<p>These bring in file classes (<code>BufferedReader</code>, <code>FileWriter</code>…), collections (<code>ArrayList</code>, <code>HashMap</code>, <code>List</code>) and two function types: <code>Function</code> and <code>Predicate</code>, used for lambdas.</p>","a":1,"c":"package storage;\n\nimport exception.DuplicateRecordException;\nimport exception.RecordNotFoundException;\n\nimport java.io.BufferedReader;\nimport java.io.BufferedWriter;\nimport java.io.File;\nimport java.io.FileReader;\nimport java.io.FileWriter;\nimport java.io.IOException;\nimport java.nio.file.Files;\nimport java.nio.file.StandardCopyOption;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.function.Function;\nimport java.util.function.Predicate;"},{"t":"Class header and fields","n":"<p><code>&lt;T&gt;</code> is a blank type filled in later: <code>Repository&lt;Loan&gt;</code> holds Loans. <code>recordName</code> is used in messages. <code>idGetter</code> is a <code>Function&lt;T, String&gt;</code>: a lambda that tells us how to get a record’s ID. <code>records</code> keeps order; <code>index</code> finds by ID.</p>","a":20,"c":"/**\n * Our own GENERIC class. It stores records of any type T and finds them by ID.\n *\n * T is a placeholder for a real type. Repository&lt;LibraryItem&gt; stores items,\n * Repository&lt;Member&gt; stores members, and so on. We write the code only once.\n *\n * It uses two collections:\n * - an ArrayList keeps the records in the order they were added (good for listing)\n * - a HashMap finds a record by its ID very quickly (good for searching)\n *\n * It can also save its records to a text file and load them back.\n *\n * @param <T> the type of record stored (for example LibraryItem)\n */\npublic class Repository<T> {\n\n    private final String recordName;           // used in messages, for example \"Item\"\n    private final Function<T, String> idGetter; // tells us how to get the ID of a record\n    private final ArrayList<T> records = new ArrayList<>();\n    private final HashMap<String, T> index = new HashMap<>();"},{"t":"Constructor","n":"<p>Saves the record name and the ID getter, for example <code>(\"Loan\", Loan::getLoanId)</code>. <code>Loan::getLoanId</code> is a <b>method reference</b>, a short lambda.</p>","a":41,"c":"    /**\n     * @param recordName a word for one record, used in messages (for example \"Member\")\n     * @param idGetter   a method that returns the ID of a record\n     *                   (for example Member::getMemberId)\n     */\n    public Repository(String recordName, Function<T, String> idGetter) {\n        this.recordName = recordName;\n        this.idGetter = idGetter;\n    }"},{"t":"normalize","n":"<p>Trims and capitalizes an ID so “s001 ” and “S001” match.</p>","a":51,"c":"    /** Makes IDs easy to compare: removes spaces and uses capital letters. */\n    private String normalize(String id) {\n        return id.trim().toUpperCase();\n    }"},{"t":"add","n":"<p>Gets the ID using the lambda. If the HashMap already has it, throw DuplicateRecordException. Otherwise add to both the list and the map. The check uses <code>containsKey</code>; flipping it with a wrong <code>!</code> would stop all adding.</p>","a":56,"c":"    /**\n     * Adds a record.\n     *\n     * @param record the record to add\n     * @throws DuplicateRecordException if a record with the same ID already exists\n     */\n    public void add(T record) throws DuplicateRecordException {\n        String id = normalize(idGetter.apply(record));\n        if (index.containsKey(id)) {\n            throw new DuplicateRecordException(recordName + \" ID '\" + id + \"' already exists.\");\n        }\n        records.add(record);\n        index.put(id, record);\n    }"},{"t":"findById","n":"<p>Looks up the map. Returns the record or <code>null</code> if there is none.</p>","a":71,"c":"    /**\n     * Finds a record by ID.\n     *\n     * @param id the ID to look for\n     * @return the record, or null if there is no record with that ID\n     */\n    public T findById(String id) {\n        return index.get(normalize(id));\n    }"},{"t":"getById","n":"<p>Same, but throws RecordNotFoundException instead of returning null. Use this when a missing record is an error.</p>","a":81,"c":"    /**\n     * Gets a record by ID. Unlike findById, it never returns null.\n     *\n     * @param id the ID to look for\n     * @return the record\n     * @throws RecordNotFoundException if there is no record with that ID\n     */\n    public T getById(String id) throws RecordNotFoundException {\n        T record = findById(id);\n        if (record == null) {\n            throw new RecordNotFoundException(recordName + \" ID '\" + normalize(id) + \"' was not found.\");\n        }\n        return record;\n    }"},{"t":"exists","n":"<p>True if the ID is in the map.</p>","a":96,"c":"    /**\n     * @param id the ID to look for\n     * @return true if a record with this ID exists\n     */\n    public boolean exists(String id) {\n        return index.containsKey(normalize(id));\n    }"},{"t":"remove","n":"<p>Finds the record (error if missing), then removes it from the list and the map.</p>","a":104,"c":"    /**\n     * Removes a record.\n     *\n     * @param id the ID of the record to remove\n     * @throws RecordNotFoundException if there is no record with that ID\n     */\n    public void remove(String id) throws RecordNotFoundException {\n        T record = getById(id);\n        records.remove(record);\n        index.remove(normalize(id));\n    }"},{"t":"getAll","n":"<p>Returns a <b>copy</b> of the list (<code>new ArrayList&lt;&gt;(records)</code>), so outside code cannot change our real list. This is encapsulation for collections.</p>","a":116,"c":"    /** @return a COPY of the list of all records, so outside code cannot damage ours */\n    public List<T> getAll() {\n        return new ArrayList<>(records);\n    }"},{"t":"findAll","n":"<p>Loops through all records and keeps those where <code>condition.test(record)</code> is true. <code>Predicate&lt;T&gt;</code> is a lambda that answers true or false, like <code>loan -&gt; !loan.isReturned()</code>.</p>","a":121,"c":"    /**\n     * Finds all records that match a condition.\n     *\n     * @param condition a Predicate (a lambda that answers true or false for one record)\n     * @return a new list with the records where the condition is true\n     */\n    public List<T> findAll(Predicate<T> condition) {\n        List<T> result = new ArrayList<>();\n        for (T record : records) {\n            if (condition.test(record)) {\n                result.add(record);\n            }\n        }\n        return result;\n    }"},{"t":"size","n":"<p>How many records there are.</p>","a":137,"c":"    /** @return the number of records */\n    public int size() {\n        return records.size();\n    }"},{"t":"saveToFile","n":"<p>1) Make sure the folder exists (<code>mkdirs</code>). 2) Write all records to a temporary <code>.tmp</code> file, one line each using <code>toLine</code>. <code>try (...)</code> closes the file automatically. 3) <code>Files.move</code> replaces the real file with the temp file. If the program fails in the middle, the old file is still safe. <code>new FileWriter(temp)</code> without <code>true</code> overwrites; with <code>true</code> it would append and create duplicates.</p>","a":142,"c":"    /**\n     * Saves all records to a text file, one record per line.\n     * It writes to a temporary file first and then replaces the real file,\n     * so a crash while saving cannot destroy the old data.\n     *\n     * @param path   the file to write\n     * @param toLine a method that turns one record into one line of text\n     * @throws IOException if the file cannot be written\n     */\n    public void saveToFile(String path, Function<T, String> toLine) throws IOException {\n        File target = new File(path);\n        File folder = target.getParentFile();\n        if (folder != null) {\n            folder.mkdirs(); // create the data folder if it does not exist\n        }\n        File temp = new File(path + \".tmp\");\n        try (BufferedWriter writer = new BufferedWriter(new FileWriter(temp))) {\n            for (T record : records) {\n                writer.write(toLine.apply(record));\n                writer.newLine();\n            }\n        } // the writer is closed automatically here\n        Files.move(temp.toPath(), target.toPath(), StandardCopyOption.REPLACE_EXISTING);\n    }"},{"t":"loadFromFile","n":"<p>Returns a list of messages. If the file is missing, it says so and returns (no crash on first run). Otherwise it reads line by line: skips blank lines, turns each line into an object with <code>fromLine</code> (a lambda), and calls <code>add</code>. If one line is broken (duplicate or any RuntimeException) it adds a “Skipped line…” message and goes on. An <code>IOException</code> is reported in a message; the catch is never empty. <code>readLine()</code> returns null at the end of the file.</p>","a":167,"c":"    /**\n     * Loads records from a text file. A missing file is not an error: we simply\n     * start with no records. A bad line is skipped and reported, never a crash.\n     *\n     * @param path     the file to read\n     * @param fromLine a method that turns one line of text into one record\n     *                 (it throws a RuntimeException if the line is bad)\n     * @return a list of warning messages (empty if everything loaded fine)\n     */\n    public List<String> loadFromFile(String path, Function<String, T> fromLine) {\n        List<String> messages = new ArrayList<>();\n        File file = new File(path);\n        if (!file.exists()) {\n            messages.add(\"File not found: \" + path + \" (starting with no \"\n                    + recordName.toLowerCase() + \" records).\");\n            return messages;\n        }\n        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {\n            int lineNumber = 0;\n            String line = reader.readLine();\n            while (line != null) {\n                lineNumber++;\n                if (!line.isBlank()) {\n                    try {\n                        add(fromLine.apply(line));\n                    } catch (DuplicateRecordException | RuntimeException e) {\n                        messages.add(\"Skipped line \" + lineNumber + \" of \" + path + \": \" + e.getMessage());\n                    }\n                }\n                line = reader.readLine(); // read the next line (null at the end of the file)\n            }\n        } catch (IOException e) {\n            messages.add(\"Could not read \" + path + \": \" + e.getMessage());\n        }\n        return messages;\n    }\n}"}]},{"file":"util/ConsoleHelper.java","sum":"<p><b>ConsoleHelper</b> handles typing and printing for the terminal. The rest of the program never uses <code>Scanner</code> or <code>System.out</code> directly. It also makes the input safe: letters typed where a number is expected will not crash the program.</p>","lines":178,"parts":[{"t":"Imports","n":"<p><code>Scanner</code> reads what the user types. <code>Locale</code> controls number format. <code>NoSuchElementException</code> is used if input ends.</p>","a":1,"c":"package util;\n\nimport java.util.Locale;\nimport java.util.NoSuchElementException;\nimport java.util.Scanner;"},{"t":"Class header and scanner","n":"<p><code>implements AutoCloseable</code> allows <code>try (ConsoleHelper console = ...)</code> in Main to close it automatically. One <code>Scanner</code> reads from <code>System.in</code> (the keyboard).</p>","a":7,"c":"/**\n * Helps the program talk with the user in the terminal.\n *\n * - It reads input safely: empty text, letters instead of numbers, and\n *   out-of-range numbers are rejected and the user is asked again.\n * - It prints messages that look different: [SUCCESS], [ERROR], [INFO],\n *   [WARNING] and [NOTICE].\n *\n * It implements AutoCloseable so we can use it in try-with-resources,\n * which closes the Scanner for us when the program ends.\n */\npublic class ConsoleHelper implements AutoCloseable {\n\n    private final Scanner scanner = new Scanner(System.in);"},{"t":"readLine","n":"<p>Prints the prompt, waits for a line, and returns it trimmed. If the input has ended (for example the user pressed Ctrl+D), it throws NoSuchElementException, which MenuController catches to save and exit.</p>","a":22,"c":"    /**\n     * Shows a prompt and reads one line.\n     *\n     * @param prompt the text to show before the user types\n     * @return what the user typed, without spaces at the start and end\n     * @throws NoSuchElementException if there is no more input (for example, input was piped in and ended)\n     */\n    public String readLine(String prompt) {\n        System.out.print(prompt);\n        if (!scanner.hasNextLine()) {\n            throw new NoSuchElementException(\"The input has ended.\");\n        }\n        return scanner.nextLine().trim();\n    }"},{"t":"readText","n":"<p><code>while (true)</code> repeats forever until we <code>return</code>. Empty text is rejected. The <code>|</code> character is rejected because we use it as the separator in data files; allowing it would corrupt the files.</p>","a":37,"c":"    /**\n     * Reads text that is not empty and does not contain the \"|\" character\n     * (we use \"|\" to separate fields in the data files). Asks again until valid.\n     *\n     * @param prompt the text to show\n     * @return the text typed by the user\n     */\n    public String readText(String prompt) {\n        while (true) {\n            String text = readLine(prompt);\n            if (text.isEmpty()) {\n                error(\"Input cannot be empty. Please try again.\");\n            } else if (text.contains(\"|\")) {\n                error(\"The '|' character is not allowed. Please try again.\");\n            } else {\n                return text;\n            }\n        }\n    }"},{"t":"readInt","n":"<p>Keeps asking until the user types a whole number between <code>min</code> and <code>max</code>. <code>continue</code> jumps back to the top of the loop. <code>Integer.parseInt</code> turns text into a number; if the text is “abc”, it throws <code>NumberFormatException</code>, which we catch and answer with a friendly message. If the number is out of range, we say the allowed range. This is why bad input never crashes the menu.</p>","a":57,"c":"    /**\n     * Reads a whole number between min and max (both included). Asks again until valid.\n     *\n     * @param prompt the text to show\n     * @param min    the smallest allowed number\n     * @param max    the largest allowed number\n     * @return the number typed by the user\n     */\n    public int readInt(String prompt, int min, int max) {\n        while (true) {\n            String text = readLine(prompt);\n            if (text.isEmpty()) {\n                error(\"Input cannot be empty. Please try again.\");\n                continue; // jump back to the start of the loop\n            }\n            try {\n                int number = Integer.parseInt(text);\n                if (number >= min && number <= max) {\n                    return number;\n                }\n                error(\"Please enter a number from \" + min + \" to \" + max + \".\");\n            } catch (NumberFormatException e) {\n                error(\"'\" + text + \"' is not a whole number. Please try again.\");\n            }\n        }\n    }"},{"t":"readYesNo","n":"<p>Accepts y, yes, n or no (any capital letters). Returns true for yes and false for no. Anything else repeats the question.</p>","a":84,"c":"    /**\n     * Asks a yes/no question. Accepts y, yes, n, no (capital letters do not matter).\n     *\n     * @param prompt the question to show\n     * @return true for yes, false for no\n     */\n    public boolean readYesNo(String prompt) {\n        while (true) {\n            String answer = readLine(prompt).toLowerCase();\n            if (answer.equals(\"y\") || answer.equals(\"yes\")) {\n                return true;\n            }\n            if (answer.equals(\"n\") || answer.equals(\"no\")) {\n                return false;\n            }\n            error(\"Please type y or n.\");\n        }\n    }"},{"t":"Message methods","n":"<p>Each prints text with a different label: <code>[SUCCESS]</code>, <code>[ERROR]</code>, <code>[INFO]</code>, <code>[WARNING]</code>, <code>[NOTICE]</code>. <code>line</code> prints plain text and <code>blank</code> prints an empty line. Different labels help the user tell results apart.</p>","a":103,"c":"    /** Prints a success message. */\n    public void success(String message) {\n        System.out.println(\"[SUCCESS] \" + message);\n    }\n\n    /** Prints an error message. */\n    public void error(String message) {\n        System.out.println(\"[ERROR] \" + message);\n    }\n\n    /** Prints an information message. */\n    public void info(String message) {\n        System.out.println(\"[INFO] \" + message);\n    }\n\n    /** Prints a warning message. */\n    public void warning(String message) {\n        System.out.println(\"[WARNING] \" + message);\n    }\n\n    /** Prints a notice (used for overdue notifications). */\n    public void notice(String message) {\n        System.out.println(\"[NOTICE] \" + message);\n    }\n\n    /** Prints one line of plain text. */\n    public void line(String text) {\n        System.out.println(text);\n    }\n\n    /** Prints an empty line. */\n    public void blank() {\n        System.out.println();\n    }"},{"t":"printf","n":"<p>Prints formatted text. <code>Object... values</code> (varargs) means “any number of values”. In formats like <code>%-8s</code>, <code>%</code> starts a code, <code>-</code> means left-align, <code>8</code> is the width, <code>s</code> is text, <code>d</code> is a whole number, <code>%n</code> is a new line. This makes tables line up.</p>","a":138,"c":"    /**\n     * Prints formatted text, like System.out.printf. Used for tables.\n     *\n     * @param format the format, for example \"%-10s %5d%n\"\n     * @param values the values that fill the format\n     */\n    public void printf(String format, Object... values) {\n        System.out.printf(format, values);\n    }"},{"t":"money","n":"<p>Turns 60.0 into “PHP 60.00”. <code>%.2f</code> means 2 digits after the decimal point. <code>Locale.US</code> makes sure a dot is used, not a comma.</p>","a":148,"c":"    /**\n     * Formats an amount of money, for example 35.0 becomes \"PHP 35.00\".\n     * Locale.US makes sure the decimal mark is always a dot.\n     *\n     * @param amount the amount in PHP\n     * @return the text\n     */\n    public static String money(double amount) {\n        return String.format(Locale.US, \"PHP %.2f\", amount);\n    }"},{"t":"cut","n":"<p>If the text is too long for a column, keep the first <code>width - 3</code> characters and add “...”. This keeps tables neat.</p>","a":159,"c":"    /**\n     * Cuts long text so tables stay lined up.\n     *\n     * @param text  the text\n     * @param width the most characters allowed\n     * @return the text, or a shortened version ending in \"...\"\n     */\n    public static String cut(String text, int width) {\n        if (text.length() <= width) {\n            return text;\n        }\n        return text.substring(0, width - 3) + \"...\";\n    }"},{"t":"close","n":"<p>Closes the scanner. Called automatically at the end of the try-with-resources in Main.</p>","a":173,"c":"    /** Closes the Scanner. Called automatically by try-with-resources. */\n    @Override\n    public void close() {\n        scanner.close();\n    }\n}"}]},{"file":"service/LibraryService.java","sum":"<p><b>LibraryService</b> holds the library rules. It is the “brain”. MenuController asks it to do things; it uses the four Repositories to store data and notifies observers when something late happens. It never prints directly (that is the menu’s job).</p>","lines":402,"parts":[{"t":"Imports","n":"<p>It imports our exceptions, models, factory, observer, repository and helper, plus Java’s <code>IOException</code>, <code>LocalDate</code>, <code>ArrayList</code> and <code>List</code>.</p>","a":1,"c":"package service;\n\nimport exception.BorrowingLimitExceededException;\nimport exception.DuplicateRecordException;\nimport exception.ItemNotAvailableException;\nimport exception.RecordNotFoundException;\nimport model.LibraryItem;\nimport model.Loan;\nimport model.Member;\nimport model.Staff;\nimport pattern.LibraryFactory;\nimport pattern.OverdueObserver;\nimport storage.Repository;\nimport util.ConsoleHelper;\n\nimport java.io.IOException;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.List;"},{"t":"Class header and fields","n":"<p>Four repositories, each created with a name and an ID getter: items, members, staff and loans. <code>LibraryItem::getItemId</code> is a method reference. <code>observers</code> is the list of listeners. <code>dataFolder</code> is where the files live.</p>","a":21,"c":"/**\n * The \"brain\" of the library. It holds all the records and enforces the rules:\n * adding, searching, borrowing, returning, fines, overdue loans, saving and loading.\n *\n * The menu never decides if a borrow is allowed. It asks this class.\n *\n * This class is also the \"subject\" of the OBSERVER PATTERN. It keeps a list of\n * OverdueObserver objects and tells them about overdue items.\n */\npublic class LibraryService {\n\n    // Four repositories: one generic class, four different record types\n    private final Repository<LibraryItem> itemRepo = new Repository<>(\"Item\", LibraryItem::getItemId);\n    private final Repository<Member> memberRepo = new Repository<>(\"Member\", Member::getMemberId);\n    private final Repository<Staff> staffRepo = new Repository<>(\"Staff\", Staff::getStaffId);\n    private final Repository<Loan> loanRepo = new Repository<>(\"Loan\", Loan::getLoanId);\n\n    private final List<OverdueObserver> observers = new ArrayList<>();\n    private final String dataFolder;"},{"t":"Constructor","n":"<p>Only saves the data folder path.</p>","a":41,"c":"    /**\n     * @param dataFolder the folder that holds the data files (for example \"data\")\n     */\n    public LibraryService(String dataFolder) {\n        this.dataFolder = dataFolder;\n    }\n\n    // ------------------------------------------------------------------\n    // Observer pattern: subject side\n    // ------------------------------------------------------------------"},{"t":"Observer methods","n":"<p><code>addObserver</code> adds a listener. <code>notifyObservers</code> loops over <b>all</b> listeners and sends the message. Using <code>get(0)</code> instead of the loop would tell only the first listener.</p>","a":52,"c":"    /**\n     * Registers an observer. It will receive every overdue notice.\n     *\n     * @param observer the observer to add\n     */\n    public void addObserver(OverdueObserver observer) {\n        observers.add(observer);\n    }\n\n    /** Sends a message to every observer. We do not know what they do with it. */\n    private void notifyObservers(String message) {\n        for (OverdueObserver observer : observers) {\n            observer.onOverdueNotice(message);\n        }\n    }"},{"t":"checkOverdueLoans","n":"<p>Runs at startup. It gets the overdue loans and, for each, builds a notice (item title, member name, due date, days late, fine so far) and sends it to the observers. It returns how many were found.</p>","a":68,"c":"    /**\n     * Looks at all open loans and notifies the observers about each overdue one.\n     *\n     * @return how many overdue loans were found\n     */\n    public int checkOverdueLoans() {\n        LocalDate today = LocalDate.now();\n        List<Loan> overdueLoans = getOverdueLoans();\n        for (Loan loan : overdueLoans) {\n            notifyObservers(\"OVERDUE: '\" + getItemTitle(loan.getItemId()) + \"' (\" + loan.getItemId()\n                    + \") borrowed by \" + getMemberName(loan.getMemberId())\n                    + \" was due on \" + loan.getDueDate()\n                    + \" (\" + loan.getDaysOverdue(today) + \" day(s) late, fine so far \"\n                    + ConsoleHelper.money(getFineSoFar(loan)) + \").\");\n        }\n        return overdueLoans.size();\n    }\n\n    // ------------------------------------------------------------------\n    // Library items\n    // ------------------------------------------------------------------"},{"t":"addItem","n":"<p>Asks the item repository to add it. A duplicate ID throws DuplicateRecordException.</p>","a":90,"c":"    /**\n     * Adds a new item.\n     *\n     * @param item the item to add\n     * @throws DuplicateRecordException if the item ID already exists\n     */\n    public void addItem(LibraryItem item) throws DuplicateRecordException {\n        itemRepo.add(item);\n    }"},{"t":"removeItem","n":"<p>Finds the item (error if missing), then checks the loan history with <code>findAll</code> and a lambda. If the item has any loan record we refuse (ItemNotAvailableException), so we never lose loan history. Otherwise we remove it.</p>","a":100,"c":"    /**\n     * Removes an item that has never been borrowed.\n     *\n     * @param itemId the ID of the item\n     * @throws RecordNotFoundException   if the item does not exist\n     * @throws ItemNotAvailableException if the item has loan records\n     */\n    public void removeItem(String itemId) throws RecordNotFoundException, ItemNotAvailableException {\n        LibraryItem item = itemRepo.getById(itemId);\n        List<Loan> history = loanRepo.findAll(loan -> loan.getItemId().equals(item.getItemId()));\n        if (!history.isEmpty()) {\n            throw new ItemNotAvailableException(\"'\" + item.getTitle()\n                    + \"' cannot be removed because it has loan records.\");\n        }\n        itemRepo.remove(item.getItemId());\n    }"},{"t":"searchItems","n":"<p>Makes the keyword lowercase, then keeps items where the ID, title, type or details <b>contains</b> it. The lambda inside <code>findAll</code> uses <code>||</code> (OR), so one match is enough.</p>","a":117,"c":"    /**\n     * Searches items. It matches the keyword against the ID, the title, the type\n     * and the details (author, ISBN, issue, publisher). Capital letters do not matter.\n     *\n     * @param keyword the word to look for\n     * @return the matching items\n     */\n    public List<LibraryItem> searchItems(String keyword) {\n        String key = keyword.trim().toLowerCase();\n        // The part after \"item ->\" is a lambda. It is true for items that match.\n        return itemRepo.findAll(item ->\n                item.getItemId().toLowerCase().contains(key)\n                        || item.getTitle().toLowerCase().contains(key)\n                        || item.getItemType().toLowerCase().contains(key)\n                        || item.getDetails().toLowerCase().contains(key));\n    }"},{"t":"getAllItemsSortedByTitle","n":"<p>Gets a copy of all items and sorts it with a lambda comparator: <code>(first, second) -&gt; first.getTitle().compareToIgnoreCase(second.getTitle())</code>. It compares two titles at a time, ignoring capitals.</p>","a":134,"c":"    /**\n     * @return all items, sorted A to Z by title\n     */\n    public List<LibraryItem> getAllItemsSortedByTitle() {\n        List<LibraryItem> sorted = itemRepo.getAll();\n        // Lambda: compare two items by title, ignoring capital letters\n        sorted.sort((first, second) -> first.getTitle().compareToIgnoreCase(second.getTitle()));\n        return sorted;\n    }"},{"t":"getItemTitle","n":"<p>Finds the item. If it is missing, return the ID text instead (so tables never crash).</p>","a":144,"c":"    /**\n     * @param itemId an item ID\n     * @return the title of the item, or the ID itself if the item is not found\n     */\n    public String getItemTitle(String itemId) {\n        LibraryItem item = itemRepo.findById(itemId);\n        return (item == null) ? itemId : item.getTitle();\n    }\n\n    // ------------------------------------------------------------------\n    // Members and staff\n    // ------------------------------------------------------------------"},{"t":"Member methods","n":"<p><code>registerMember</code> adds a member. <code>getAllMembers</code> returns all. <code>getMemberName</code> returns the name, or the ID if not found.</p>","a":157,"c":"    /**\n     * Registers a new member.\n     *\n     * @param member the member to add\n     * @throws DuplicateRecordException if the member ID already exists\n     */\n    public void registerMember(Member member) throws DuplicateRecordException {\n        memberRepo.add(member);\n    }\n\n    /** @return all members in the order they were registered */\n    public List<Member> getAllMembers() {\n        return memberRepo.getAll();\n    }\n\n    /**\n     * @param memberId a member ID\n     * @return the name of the member, or the ID itself if the member is not found\n     */\n    public String getMemberName(String memberId) {\n        Member member = memberRepo.findById(memberId);\n        return (member == null) ? memberId : member.getName();\n    }"},{"t":"Staff methods","n":"<p>Add a staff member or list all staff.</p>","a":181,"c":"    /**\n     * Adds a staff member.\n     *\n     * @param staff the staff member to add\n     * @throws DuplicateRecordException if the staff ID already exists\n     */\n    public void addStaff(Staff staff) throws DuplicateRecordException {\n        staffRepo.add(staff);\n    }\n\n    /** @return all staff in the order they were added */\n    public List<Staff> getAllStaff() {\n        return staffRepo.getAll();\n    }\n\n    // ------------------------------------------------------------------\n    // Borrowing and returning\n    // ------------------------------------------------------------------"},{"t":"borrowItem","n":"<p>Step by step: find the item, member and staff (RecordNotFoundException if missing); refuse if the item is not available; count the member’s open loans and refuse if it reached the limit (<code>&gt;=</code>); create the loan with today’s date and a due date of today + the member’s loan days; add it; mark the item borrowed. The <code>try/catch</code> around <code>loanRepo.add</code> handles a very unlikely ID clash. Note that the item is marked borrowed <b>last</b>, only after everything succeeded.</p>","a":200,"c":"    /**\n     * Lends an item to a member.\n     *\n     * @param itemId   the item to borrow\n     * @param memberId the member who borrows\n     * @param staffId  the staff member who handles the loan\n     * @return the new loan\n     * @throws RecordNotFoundException           if the item, member or staff ID does not exist\n     * @throws ItemNotAvailableException         if the item is already borrowed\n     * @throws BorrowingLimitExceededException   if the member is at their borrowing limit\n     */\n    public Loan borrowItem(String itemId, String memberId, String staffId)\n            throws RecordNotFoundException, ItemNotAvailableException, BorrowingLimitExceededException {\n        LibraryItem item = itemRepo.getById(itemId);\n        Member member = memberRepo.getById(memberId);\n        staffRepo.getById(staffId); // only checks that this staff member exists\n\n        if (!item.isAvailable()) {\n            throw new ItemNotAvailableException(\"'\" + item.getTitle() + \"' is already borrowed.\");\n        }\n        int openLoans = countOpenLoans(member.getMemberId());\n        if (openLoans >= member.getMaxItems()) {\n            throw new BorrowingLimitExceededException(member.getName() + \" already has \" + openLoans\n                    + \" borrowed item(s). The limit for a \" + member.getMemberType().toLowerCase()\n                    + \" is \" + member.getMaxItems() + \".\", member.getMaxItems());\n        }\n\n        LocalDate today = LocalDate.now();\n        Loan loan = new Loan(nextLoanId(), item.getItemId(), member.getMemberId(),\n                staffRepo.getById(staffId).getStaffId(), today, today.plusDays(member.getLoanDays()));\n        try {\n            loanRepo.add(loan);\n        } catch (DuplicateRecordException e) {\n            // nextLoanId() always gives a new ID, so this should never happen\n            throw new IllegalStateException(\"Loan ID clash: \" + e.getMessage());\n        }\n        item.markBorrowed();\n        return loan;\n    }"},{"t":"returnItem","n":"<p>Find the item, then its open loan (error if none). Count the days late and ask the <b>member’s policy</b> for the fine. Close the loan, mark the item returned, and if there is a fine tell the observers. Returns the loan so the menu can show it.</p>","a":240,"c":"    /**\n     * Returns an item. If it is late, the fine is calculated and stored in the loan.\n     *\n     * @param itemId the item that comes back\n     * @return the loan that was closed (check getFineAmount() for a fine)\n     * @throws RecordNotFoundException if the item does not exist or is not currently borrowed\n     */\n    public Loan returnItem(String itemId) throws RecordNotFoundException {\n        LibraryItem item = itemRepo.getById(itemId);\n        Loan loan = findOpenLoanForItem(item.getItemId());\n        if (loan == null) {\n            throw new RecordNotFoundException(\"'\" + item.getTitle()\n                    + \"' is not currently borrowed, so it cannot be returned.\");\n        }\n\n        LocalDate today = LocalDate.now();\n        Member member = memberRepo.getById(loan.getMemberId());\n        int daysLate = loan.getDaysOverdue(today);\n        double fine = member.calculateFine(daysLate); // the member's policy does the math\n\n        loan.markReturned(today, fine);\n        item.markReturned();\n\n        if (fine > 0) {\n            notifyObservers(\"LATE RETURN: '\" + item.getTitle() + \"' was returned \" + daysLate\n                    + \" day(s) late by \" + member.getName() + \". Fine: \" + ConsoleHelper.money(fine) + \".\");\n        }\n        return loan;\n    }"},{"t":"Private helpers","n":"<p><code>countOpenLoans</code> counts loans of one member that are not returned. <code>findOpenLoanForItem</code> loops until it finds a loan with this item <b>and</b> not returned (<code>&amp;&amp;</code>); returns null if none. <code>nextLoanId</code> makes IDs like L0004: <code>%04d</code> pads the number with zeros to 4 digits; the <code>while</code> loop skips IDs that already exist.</p>","a":270,"c":"    /** Counts the loans of one member that are not returned yet. */\n    private int countOpenLoans(String memberId) {\n        return loanRepo.findAll(loan -> loan.getMemberId().equals(memberId) && !loan.isReturned()).size();\n    }\n\n    /** Finds the open (not returned) loan of an item, or null if there is none. */\n    private Loan findOpenLoanForItem(String itemId) {\n        for (Loan loan : loanRepo.getAll()) {\n            if (loan.getItemId().equals(itemId) && !loan.isReturned()) {\n                return loan;\n            }\n        }\n        return null;\n    }\n\n    /** Makes a new loan ID like L0001, L0002, ... that is not used yet. */\n    private String nextLoanId() {\n        int number = loanRepo.size() + 1;\n        String id = String.format(\"L%04d\", number);\n        while (loanRepo.exists(id)) {\n            number++;\n            id = String.format(\"L%04d\", number);\n        }\n        return id;\n    }\n\n    // ------------------------------------------------------------------\n    // Loans, overdue loans and fines\n    // ------------------------------------------------------------------"},{"t":"Loan queries","n":"<p><code>getAllLoans</code> returns all loans. <code>getOverdueLoans</code> uses a lambda with <code>loan.isOverdue(today)</code>. <code>getFineSoFar</code> asks the member’s policy for the fine of days late so far (0 if the member is missing). <code>getLoansWithFines</code> keeps loans with a fine.</p>","a":300,"c":"    /** @return all loans (open and returned) */\n    public List<Loan> getAllLoans() {\n        return loanRepo.getAll();\n    }\n\n    /**\n     * @return the loans that are not returned and are past their due date\n     */\n    public List<Loan> getOverdueLoans() {\n        LocalDate today = LocalDate.now();\n        return loanRepo.findAll(loan -> loan.isOverdue(today));\n    }\n\n    /**\n     * Works out the fine so far for a loan that is still open and overdue.\n     * (This amount is calculated now. It is not stored until the item is returned.)\n     *\n     * @param loan the loan\n     * @return the fine in PHP (0 if the loan is not late)\n     */\n    public double getFineSoFar(Loan loan) {\n        Member member = memberRepo.findById(loan.getMemberId());\n        if (member == null) {\n            return 0.0;\n        }\n        return member.calculateFine(loan.getDaysOverdue(LocalDate.now()));\n    }\n\n    /** @return the loans that have a fine (paid or unpaid) */\n    public List<Loan> getLoansWithFines() {\n        return loanRepo.findAll(loan -> loan.hasFine());\n    }"},{"t":"payFine","n":"<p>Finds the loan. If it has no fine or is already paid, throw an error; otherwise mark the fine paid.</p>","a":333,"c":"    /**\n     * Marks the fine of a loan as paid.\n     *\n     * @param loanId the loan ID\n     * @throws RecordNotFoundException if the loan does not exist or has no unpaid fine\n     */\n    public void payFine(String loanId) throws RecordNotFoundException {\n        Loan loan = loanRepo.getById(loanId);\n        if (!loan.hasFine() || loan.isFinePaid()) {\n            throw new RecordNotFoundException(\"Loan \" + loan.getLoanId() + \" has no unpaid fine.\");\n        }\n        loan.markFinePaid();\n    }\n\n    // ------------------------------------------------------------------\n    // Saving and loading\n    // ------------------------------------------------------------------"},{"t":"saveAll","n":"<p>Saves the four repositories to <code>items.txt</code>, <code>members.txt</code>, <code>staff.txt</code> and <code>loans.txt</code> using each class’s <code>toFileLine</code> (method references). It <code>throws IOException</code>, so the menu must handle a failed save.</p>","a":351,"c":"    /**\n     * Saves all records to the data files.\n     *\n     * @throws IOException if a file cannot be written\n     */\n    public void saveAll() throws IOException {\n        itemRepo.saveToFile(dataFolder + \"/items.txt\", LibraryItem::toFileLine);\n        memberRepo.saveToFile(dataFolder + \"/members.txt\", Member::toFileLine);\n        staffRepo.saveToFile(dataFolder + \"/staff.txt\", Staff::toFileLine);\n        loanRepo.saveToFile(dataFolder + \"/loans.txt\", Loan::toFileLine);\n    }"},{"t":"loadAll","n":"<p>Loads the four files in order (items, members, staff, then loans, because loans refer to the others). Every warning message is collected. Then it loops through the loans: any loan that is <b>not</b> returned marks its item as borrowed, so the shelf matches the loan records after a restart.</p>","a":363,"c":"    /**\n     * Loads all records from the data files. Missing files and bad lines\n     * are reported in the returned list and never crash the program.\n     *\n     * @return warning messages (empty if everything loaded fine)\n     */\n    public List<String> loadAll() {\n        List<String> messages = new ArrayList<>();\n        messages.addAll(itemRepo.loadFromFile(dataFolder + \"/items.txt\", LibraryFactory::createItemFromLine));\n        messages.addAll(memberRepo.loadFromFile(dataFolder + \"/members.txt\", LibraryFactory::createMemberFromLine));\n        messages.addAll(staffRepo.loadFromFile(dataFolder + \"/staff.txt\", Staff::fromFileLine));\n        messages.addAll(loanRepo.loadFromFile(dataFolder + \"/loans.txt\", this::parseLoanLine));\n\n        // The items file does not store \"available\". We work it out from the open loans.\n        for (Loan loan : loanRepo.getAll()) {\n            if (!loan.isReturned()) {\n                itemRepo.findById(loan.getItemId()).markBorrowed();\n            }\n        }\n        return messages;\n    }"},{"t":"parseLoanLine","n":"<p>Reads one loan line, then checks it makes sense: the item, member and staff IDs must exist, and an open loan cannot be a second open loan for the same item. A bad line throws an error and is skipped with a warning.</p>","a":385,"c":"    /** Reads one loan line and checks that the item, member and staff really exist. */\n    private Loan parseLoanLine(String line) {\n        Loan loan = Loan.fromFileLine(line);\n        if (!itemRepo.exists(loan.getItemId())) {\n            throw new IllegalArgumentException(\"unknown item ID \" + loan.getItemId());\n        }\n        if (!memberRepo.exists(loan.getMemberId())) {\n            throw new IllegalArgumentException(\"unknown member ID \" + loan.getMemberId());\n        }\n        if (!staffRepo.exists(loan.getStaffId())) {\n            throw new IllegalArgumentException(\"unknown staff ID \" + loan.getStaffId());\n        }\n        if (!loan.isReturned() && findOpenLoanForItem(loan.getItemId()) != null) {\n            throw new IllegalArgumentException(\"item \" + loan.getItemId() + \" already has an open loan\");\n        }\n        return loan;\n    }\n}"}]},{"file":"app/MenuController.java","sum":"<p><b>MenuController</b> is the screen of the program. It prints menus, reads what the user types (through ConsoleHelper), calls LibraryService, and prints results. It contains <b>no library rules</b>. Its pattern for each feature is always the same: ask for input → call the service inside <code>try</code> → print success → <code>catch</code> and print <code>e.getMessage()</code>.</p>","lines":576,"parts":[{"t":"Imports","n":"<p>It uses the exceptions, models, factory, service and console helper, plus input/output and date classes.</p>","a":1,"c":"package app;\n\nimport exception.LibraryException;\nimport model.LibraryItem;\nimport model.Loan;\nimport model.Member;\nimport model.Staff;\nimport pattern.LibraryFactory;\nimport service.LibraryService;\nimport util.ConsoleHelper;\n\nimport java.io.IOException;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.NoSuchElementException;"},{"t":"Class header and fields","n":"<p>It holds the console, the service, and <code>notificationLog</code>, a list of notices from this session for menu option 9.</p>","a":18,"c":"/**\n * Shows the menus, reads what the user types, and calls the LibraryService.\n *\n * This class does NOT contain library rules. It only asks questions, calls the\n * service, and prints the results or the error messages.\n *\n * After every action that changes data, it calls autoSave().\n */\npublic class MenuController {\n\n    private final ConsoleHelper console;\n    private final LibraryService service;\n    private final List<String> notificationLog = new ArrayList<>(); // remembers notices of this session"},{"t":"Constructor","n":"<p>The pieces are handed in from Main (<b>dependency passing</b>), so this class does not create them itself.</p>","a":32,"c":"    /**\n     * @param console the helper that reads and prints\n     * @param service the service that holds the library data and rules\n     */\n    public MenuController(ConsoleHelper console, LibraryService service) {\n        this.console = console;\n        this.service = service;\n    }"},{"t":"run","n":"<p>The public starting point. It calls <code>startUp()</code> then <code>mainMenuLoop()</code>. If the input ends suddenly (NoSuchElementException from ConsoleHelper), it prints a message and saves so no data is lost.</p>","a":41,"c":"    /**\n     * Runs the program: loads data, shows the main menu until the user exits.\n     */\n    public void run() {\n        startUp();\n        try {\n            mainMenuLoop();\n        } catch (NoSuchElementException e) {\n            // The input ended (for example, a file was piped in). Save and stop politely.\n            console.blank();\n            console.info(\"The input has ended. Saving and exiting.\");\n            autoSave();\n        }\n    }\n\n    // ------------------------------------------------------------------\n    // Start up and main menu\n    // ------------------------------------------------------------------"},{"t":"startUp","n":"<p>Prints the title, loads the data and shows every warning (missing file, skipped lines). Then it adds the two <b>observers</b> with lambdas: <code>message -&gt; console.notice(message)</code> shows the notice now; <code>message -&gt; notificationLog.add(message)</code> remembers it. Last it runs <code>checkOverdueLoans()</code>; if the count is 0 it says there are no overdue loans.</p>","a":60,"c":"    /** Loads the data, connects the observers, and checks for overdue items. */\n    private void startUp() {\n        console.line(\"=== LIBRARY MANAGEMENT SYSTEM ===\");\n        console.info(\"Loading data...\");\n        List<String> messages = service.loadAll();\n        for (String message : messages) {\n            console.warning(message);\n        }\n\n        // OBSERVER PATTERN: we register two observers, written as lambdas.\n        // Observer 1 shows the notice on the screen right away.\n        service.addObserver(message -> console.notice(message));\n        // Observer 2 remembers the notice, so menu option 9 can show it later.\n        service.addObserver(message -> notificationLog.add(message));\n\n        int overdueCount = service.checkOverdueLoans();\n        if (overdueCount == 0) {\n            console.info(\"No overdue loans.\");\n        }\n    }"},{"t":"mainMenuLoop","n":"<p><code>while (running)</code> repeats until the user picks 0. <code>readInt(..., 0, 10)</code> only returns 0–10. The <code>switch</code> sends each number to a method; <code>break</code> ends each case. Choice 0 only stops the loop if <code>saveBeforeExit()</code> returns true.</p>","a":81,"c":"    /** Shows the main menu again and again until the user chooses Exit. */\n    private void mainMenuLoop() {\n        boolean running = true;\n        while (running) {\n            printMainMenu();\n            int choice = console.readInt(\"Enter choice [0-10]: \", 0, 10);\n            switch (choice) {\n                case 1:\n                    manageItems();\n                    break;\n                case 2:\n                    manageMembers();\n                    break;\n                case 3:\n                    manageStaff();\n                    break;\n                case 4:\n                    borrowItem();\n                    break;\n                case 5:\n                    returnItem();\n                    break;\n                case 6:\n                    viewAllLoans();\n                    break;\n                case 7:\n                    viewOverdueLoans();\n                    break;\n                case 8:\n                    viewFines();\n                    break;\n                case 9:\n                    viewNotifications();\n                    break;\n                case 10:\n                    saveNow();\n                    break;\n                case 0:\n                    if (saveBeforeExit()) {\n                        running = false;\n                    }\n                    break;\n                default:\n                    break; // readInt already limits the choice, so we never get here\n            }\n        }\n        console.info(\"Goodbye!\");\n    }"},{"t":"printMainMenu","n":"<p>Prints the eleven numbered options.</p>","a":130,"c":"    /** Prints the main menu. */\n    private void printMainMenu() {\n        console.blank();\n        console.line(\"=== LIBRARY MANAGEMENT SYSTEM ===\");\n        console.line(\"[1]  Manage Library Items\");\n        console.line(\"[2]  Manage Members\");\n        console.line(\"[3]  Manage Staff\");\n        console.line(\"[4]  Borrow an Item\");\n        console.line(\"[5]  Return an Item\");\n        console.line(\"[6]  View All Loans\");\n        console.line(\"[7]  View Overdue Loans\");\n        console.line(\"[8]  View Fines\");\n        console.line(\"[9]  View Notifications\");\n        console.line(\"[10] Save Data\");\n        console.line(\"[0]  Save and Exit\");\n    }\n\n    // ------------------------------------------------------------------\n    // Saving\n    // ------------------------------------------------------------------"},{"t":"Saving methods","n":"<p><code>autoSave</code> is called after each change and only shows a warning if saving fails. <code>saveNow</code> (option 10) shows success or error. <code>saveBeforeExit</code> saves; if it fails, it asks “Exit without saving?” and returns the answer.</p>","a":151,"c":"    /** Saves after a change. A failure is shown as a warning, not a crash. */\n    private void autoSave() {\n        try {\n            service.saveAll();\n            console.info(\"Data saved automatically.\");\n        } catch (IOException e) {\n            console.warning(\"Could not save the data: \" + e.getMessage());\n        }\n    }\n\n    /** Saves when the user chooses \"Save Data\". */\n    private void saveNow() {\n        try {\n            service.saveAll();\n            console.success(\"All data saved.\");\n        } catch (IOException e) {\n            console.error(\"Could not save the data: \" + e.getMessage());\n        }\n    }\n\n    /**\n     * Saves before leaving the program.\n     *\n     * @return true if it is OK to exit (saved, or the user chose to exit without saving)\n     */\n    private boolean saveBeforeExit() {\n        try {\n            service.saveAll();\n            console.success(\"All data saved.\");\n            return true;\n        } catch (IOException e) {\n            console.error(\"Could not save the data: \" + e.getMessage());\n            return console.readYesNo(\"Exit without saving? (y/n): \");\n        }\n    }\n\n    // ------------------------------------------------------------------\n    // Library items\n    // ------------------------------------------------------------------"},{"t":"manageItems (sub-menu)","n":"<p>A smaller menu with its own loop. <code>inMenu</code> turns false on 0 (the <code>default</code> case), which goes back to the main menu.</p>","a":191,"c":"    /** The submenu for library items. */\n    private void manageItems() {\n        boolean inMenu = true;\n        while (inMenu) {\n            console.blank();\n            console.line(\"--- Manage Library Items ---\");\n            console.line(\"[1] Add an item\");\n            console.line(\"[2] Search items\");\n            console.line(\"[3] List all items\");\n            console.line(\"[4] Remove an item\");\n            console.line(\"[0] Back\");\n            int choice = console.readInt(\"Enter choice [0-4]: \", 0, 4);\n            switch (choice) {\n                case 1:\n                    addItem();\n                    break;\n                case 2:\n                    searchItems();\n                    break;\n                case 3:\n                    printItemTable(service.getAllItemsSortedByTitle());\n                    break;\n                case 4:\n                    removeItem();\n                    break;\n                default:\n                    inMenu = false;\n                    break;\n            }\n        }\n    }"},{"t":"addItem","n":"<p>Asks for the type (1 or 2), then the ID, title and two details; the prompts change with a short if-else (<code>kind == 1 ? ... : ...</code>). In <code>try</code> it calls the <b>Factory</b> to build the item and the service to add it. <code>catch (LibraryException | IllegalArgumentException e)</code> handles both our errors and bad values, and prints only the message (no stack trace).</p>","a":223,"c":"    /** Asks for the details of a new book or magazine and adds it. */\n    private void addItem() {\n        console.line(\"[1] Book\");\n        console.line(\"[2] Magazine\");\n        int kind = console.readInt(\"Item type [1-2]: \", 1, 2);\n        String type = (kind == 1) ? \"BOOK\" : \"MAGAZINE\";\n\n        String id = console.readText(\"Item ID: \");\n        String title = console.readText(\"Title: \");\n        String detail1 = console.readText(kind == 1 ? \"Author: \" : \"Issue (for example Issue 12): \");\n        String detail2 = console.readText(kind == 1 ? \"ISBN: \" : \"Publisher: \");\n\n        try {\n            // The factory decides whether to create a Book or a Magazine\n            LibraryItem item = LibraryFactory.createItem(type, id, title, detail1, detail2);\n            service.addItem(item);\n            console.success(item.getItemType() + \" '\" + item.getTitle() + \"' added with ID \" + item.getItemId() + \".\");\n            autoSave();\n        } catch (LibraryException | IllegalArgumentException e) {\n            console.error(e.getMessage());\n        }\n    }"},{"t":"searchItems","n":"<p>Asks for a keyword, calls the service, then says “No items match” or shows the table.</p>","a":246,"c":"    /** Asks for a keyword and shows the matching items. */\n    private void searchItems() {\n        String keyword = console.readText(\"Search for (title, author, type, ID...): \");\n        List<LibraryItem> results = service.searchItems(keyword);\n        if (results.isEmpty()) {\n            console.info(\"No items match '\" + keyword + \"'.\");\n        } else {\n            console.info(results.size() + \" item(s) found.\");\n            printItemTable(results);\n        }\n    }"},{"t":"removeItem","n":"<p>Asks for an ID and a yes/no confirmation. If the answer is no, it stops with <code>return</code>. Otherwise it calls the service and catches a LibraryException (such as “has loan records”).</p>","a":258,"c":"    /** Asks for an item ID and removes the item after confirmation. */\n    private void removeItem() {\n        String id = console.readText(\"ID of the item to remove: \");\n        if (!console.readYesNo(\"Really remove item \" + id.toUpperCase() + \"? (y/n): \")) {\n            console.info(\"Nothing was removed.\");\n            return;\n        }\n        try {\n            service.removeItem(id);\n            console.success(\"Item \" + id.toUpperCase() + \" removed.\");\n            autoSave();\n        } catch (LibraryException e) {\n            console.error(e.getMessage());\n        }\n    }"},{"t":"printItemTable","n":"<p>If the list is empty it says so. Otherwise it prints a header, a line of 100 dashes (<code>\"-\".repeat(100)</code>), then one row per item. <code>ConsoleHelper.cut</code> shortens long text. <code>item.isAvailable() ? \"Available\" : \"Borrowed\"</code> picks the status word.</p>","a":274,"c":"    /** Prints items as a table. Book and Magazine objects are handled the same way. */\n    private void printItemTable(List<LibraryItem> items) {\n        if (items.isEmpty()) {\n            console.info(\"There are no items yet.\");\n            return;\n        }\n        console.printf(\"%-8s %-9s %-30s %-40s %-9s%n\", \"ID\", \"Type\", \"Title\", \"Details\", \"Status\");\n        console.line(\"-\".repeat(100));\n        for (LibraryItem item : items) {\n            // POLYMORPHISM: getItemType() and getDetails() run the version of the real object\n            console.printf(\"%-8s %-9s %-30s %-40s %-9s%n\",\n                    item.getItemId(),\n                    item.getItemType(),\n                    ConsoleHelper.cut(item.getTitle(), 30),\n                    ConsoleHelper.cut(item.getDetails(), 40),\n                    item.isAvailable() ? \"Available\" : \"Borrowed\");\n        }\n    }\n\n    // ------------------------------------------------------------------\n    // Members\n    // ------------------------------------------------------------------"},{"t":"manageMembers (sub-menu)","n":"<p>Same structure as manageItems with two options.</p>","a":297,"c":"    /** The submenu for members. */\n    private void manageMembers() {\n        boolean inMenu = true;\n        while (inMenu) {\n            console.blank();\n            console.line(\"--- Manage Members ---\");\n            console.line(\"[1] Register a member\");\n            console.line(\"[2] List all members\");\n            console.line(\"[0] Back\");\n            int choice = console.readInt(\"Enter choice [0-2]: \", 0, 2);\n            switch (choice) {\n                case 1:\n                    registerMember();\n                    break;\n                case 2:\n                    printMemberTable(service.getAllMembers());\n                    break;\n                default:\n                    inMenu = false;\n                    break;\n            }\n        }\n    }"},{"t":"registerMember","n":"<p>Asks type, ID, name and course or department. The Factory builds the Student or Faculty member with the right policy. The success message shows the limit and days, which come from the policy.</p>","a":321,"c":"    /** Asks for the details of a new student or faculty member and registers them. */\n    private void registerMember() {\n        console.line(\"[1] Student\");\n        console.line(\"[2] Faculty\");\n        int kind = console.readInt(\"Member type [1-2]: \", 1, 2);\n        String type = (kind == 1) ? \"STUDENT\" : \"FACULTY\";\n\n        String id = console.readText(\"Member ID: \");\n        String name = console.readText(\"Name: \");\n        String detail = console.readText(kind == 1 ? \"Course (for example BSIT): \" : \"Department: \");\n\n        try {\n            Member member = LibraryFactory.createMember(type, id, name, detail);\n            service.registerMember(member);\n            console.success(member.getMemberType() + \" '\" + member.getName() + \"' registered with ID \"\n                    + member.getMemberId() + \". Limit: \" + member.getMaxItems() + \" items for \"\n                    + member.getLoanDays() + \" days.\");\n            autoSave();\n        } catch (LibraryException | IllegalArgumentException e) {\n            console.error(e.getMessage());\n        }\n    }"},{"t":"printMemberTable","n":"<p>Prints members with ID, type, name, course/department, max items and loan days. <code>%-8d</code> prints a whole number.</p>","a":344,"c":"    /** Prints members as a table. */\n    private void printMemberTable(List<Member> members) {\n        if (members.isEmpty()) {\n            console.info(\"There are no members yet.\");\n            return;\n        }\n        console.printf(\"%-8s %-9s %-24s %-22s %-8s %-9s%n\",\n                \"ID\", \"Type\", \"Name\", \"Course / Department\", \"Max\", \"Loan days\");\n        console.line(\"-\".repeat(86));\n        for (Member member : members) {\n            console.printf(\"%-8s %-9s %-24s %-22s %-8d %-9d%n\",\n                    member.getMemberId(),\n                    member.getMemberType(),\n                    ConsoleHelper.cut(member.getName(), 24),\n                    ConsoleHelper.cut(member.getExtraInfo(), 22),\n                    member.getMaxItems(),\n                    member.getLoanDays());\n        }\n    }\n\n    // ------------------------------------------------------------------\n    // Staff\n    // ------------------------------------------------------------------"},{"t":"manageStaff (sub-menu)","n":"<p>Same structure again.</p>","a":368,"c":"    /** The submenu for staff. */\n    private void manageStaff() {\n        boolean inMenu = true;\n        while (inMenu) {\n            console.blank();\n            console.line(\"--- Manage Staff ---\");\n            console.line(\"[1] Add a staff member\");\n            console.line(\"[2] List all staff\");\n            console.line(\"[0] Back\");\n            int choice = console.readInt(\"Enter choice [0-2]: \", 0, 2);\n            switch (choice) {\n                case 1:\n                    addStaff();\n                    break;\n                case 2:\n                    printStaffTable(service.getAllStaff());\n                    break;\n                default:\n                    inMenu = false;\n                    break;\n            }\n        }\n    }"},{"t":"addStaff","n":"<p>Asks for ID, name and role; builds the Staff directly with <code>new Staff(...)</code> (no factory needed because there is only one kind); adds it with the service.</p>","a":392,"c":"    /** Asks for the details of a new staff member and adds them. */\n    private void addStaff() {\n        String id = console.readText(\"Staff ID: \");\n        String name = console.readText(\"Name: \");\n        String role = console.readText(\"Role (for example Librarian): \");\n        try {\n            Staff staff = new Staff(id, name, role);\n            service.addStaff(staff);\n            console.success(\"Staff member '\" + staff.getName() + \"' added with ID \" + staff.getStaffId() + \".\");\n            autoSave();\n        } catch (LibraryException | IllegalArgumentException e) {\n            console.error(e.getMessage());\n        }\n    }"},{"t":"printStaffTable","n":"<p>Prints the staff table.</p>","a":407,"c":"    /** Prints staff as a table. */\n    private void printStaffTable(List<Staff> staffList) {\n        if (staffList.isEmpty()) {\n            console.info(\"There are no staff members yet.\");\n            return;\n        }\n        console.printf(\"%-8s %-24s %-24s%n\", \"ID\", \"Name\", \"Role\");\n        console.line(\"-\".repeat(58));\n        for (Staff staff : staffList) {\n            console.printf(\"%-8s %-24s %-24s%n\",\n                    staff.getStaffId(),\n                    ConsoleHelper.cut(staff.getName(), 24),\n                    ConsoleHelper.cut(staff.getRole(), 24));\n        }\n    }\n\n    // ------------------------------------------------------------------\n    // Borrowing and returning\n    // ------------------------------------------------------------------"},{"t":"borrowItem (menu option 4)","n":"<p>Asks for item, member and staff IDs. Calls <code>service.borrowItem</code>. On success it shows the loan ID and due date. The catch prints the reason if the item is borrowed, the limit is reached, or an ID is missing. <b>Path to remember:</b> menu 4 → borrowItem() → service.borrowItem() → Loan + item.markBorrowed() → autoSave() → files.</p>","a":427,"c":"    /** Asks who borrows what and creates the loan. */\n    private void borrowItem() {\n        console.blank();\n        console.line(\"--- Borrow an Item ---\");\n        String itemId = console.readText(\"Item ID: \");\n        String memberId = console.readText(\"Member ID: \");\n        String staffId = console.readText(\"Staff ID (who handles the loan): \");\n        try {\n            Loan loan = service.borrowItem(itemId, memberId, staffId);\n            console.success(\"Loan \" + loan.getLoanId() + \" created. '\" + service.getItemTitle(loan.getItemId())\n                    + \"' is due on \" + loan.getDueDate() + \".\");\n            autoSave();\n        } catch (LibraryException e) {\n            console.error(e.getMessage());\n        }\n    }"},{"t":"returnItem (menu option 5)","n":"<p>Asks for the item ID and calls <code>service.returnItem</code>. If the loan has a fine, it shows a warning with the amount and mentions option 8 for paying.</p>","a":444,"c":"    /** Asks which item comes back and closes its loan. */\n    private void returnItem() {\n        console.blank();\n        console.line(\"--- Return an Item ---\");\n        String itemId = console.readText(\"Item ID: \");\n        try {\n            Loan loan = service.returnItem(itemId);\n            console.success(\"'\" + service.getItemTitle(loan.getItemId()) + \"' returned (loan \"\n                    + loan.getLoanId() + \").\");\n            if (loan.hasFine()) {\n                console.warning(\"The item was late. Fine: \" + ConsoleHelper.money(loan.getFineAmount())\n                        + \". You can pay it in menu option 8.\");\n            }\n            autoSave();\n        } catch (LibraryException e) {\n            console.error(e.getMessage());\n        }\n    }\n\n    // ------------------------------------------------------------------\n    // Loans, overdue loans, fines, notifications\n    // ------------------------------------------------------------------"},{"t":"viewAllLoans (option 6)","n":"<p>Prints every loan. For each, the status is chosen with if / else if: Returned, OVERDUE, or Open. It looks up the item title and member name through the service.</p>","a":467,"c":"    /** Shows every loan. */\n    private void viewAllLoans() {\n        List<Loan> loans = service.getAllLoans();\n        if (loans.isEmpty()) {\n            console.info(\"There are no loans yet.\");\n            return;\n        }\n        LocalDate today = LocalDate.now();\n        console.blank();\n        console.printf(\"%-7s %-7s %-24s %-18s %-10s %-10s %-9s%n\",\n                \"Loan\", \"Item\", \"Title\", \"Member\", \"Borrowed\", \"Due\", \"Status\");\n        console.line(\"-\".repeat(92));\n        for (Loan loan : loans) {\n            String status;\n            if (loan.isReturned()) {\n                status = \"Returned\";\n            } else if (loan.isOverdue(today)) {\n                status = \"OVERDUE\";\n            } else {\n                status = \"Open\";\n            }\n            console.printf(\"%-7s %-7s %-24s %-18s %-10s %-10s %-9s%n\",\n                    loan.getLoanId(),\n                    loan.getItemId(),\n                    ConsoleHelper.cut(service.getItemTitle(loan.getItemId()), 24),\n                    ConsoleHelper.cut(service.getMemberName(loan.getMemberId()), 18),\n                    loan.getBorrowDate(),\n                    loan.getDueDate(),\n                    status);\n        }\n    }"},{"t":"viewOverdueLoans (option 7)","n":"<p>Lists only overdue loans with days late and fine so far, and adds the fines into <code>total</code> (<code>+=</code> adds to the variable).</p>","a":499,"c":"    /** Shows the loans that are past their due date, with the fine so far. */\n    private void viewOverdueLoans() {\n        List<Loan> overdue = service.getOverdueLoans();\n        if (overdue.isEmpty()) {\n            console.info(\"There are no overdue loans.\");\n            return;\n        }\n        LocalDate today = LocalDate.now();\n        double total = 0;\n        console.blank();\n        console.printf(\"%-7s %-24s %-18s %-10s %-10s %-12s%n\",\n                \"Loan\", \"Title\", \"Member\", \"Due\", \"Days late\", \"Fine so far\");\n        console.line(\"-\".repeat(86));\n        for (Loan loan : overdue) {\n            double fine = service.getFineSoFar(loan);\n            total += fine;\n            console.printf(\"%-7s %-24s %-18s %-10s %-10d %-12s%n\",\n                    loan.getLoanId(),\n                    ConsoleHelper.cut(service.getItemTitle(loan.getItemId()), 24),\n                    ConsoleHelper.cut(service.getMemberName(loan.getMemberId()), 18),\n                    loan.getDueDate(),\n                    loan.getDaysOverdue(today),\n                    ConsoleHelper.money(fine));\n        }\n        console.info(overdue.size() + \" overdue loan(s). Total fines so far: \" + ConsoleHelper.money(total));\n    }"},{"t":"viewFines (option 8)","n":"<p>Lists loans with fines and totals the unpaid ones. If there is unpaid money and the user says yes, it asks for a loan ID and calls <code>payFine</code>.</p>","a":526,"c":"    /** Shows the fines of returned items and lets the user pay one. */\n    private void viewFines() {\n        List<Loan> fines = service.getLoansWithFines();\n        if (fines.isEmpty()) {\n            console.info(\"There are no fines.\");\n            return;\n        }\n        double unpaidTotal = 0;\n        console.blank();\n        console.printf(\"%-7s %-24s %-18s %-14s %-8s%n\", \"Loan\", \"Title\", \"Member\", \"Fine\", \"Status\");\n        console.line(\"-\".repeat(76));\n        for (Loan loan : fines) {\n            if (!loan.isFinePaid()) {\n                unpaidTotal += loan.getFineAmount();\n            }\n            console.printf(\"%-7s %-24s %-18s %-14s %-8s%n\",\n                    loan.getLoanId(),\n                    ConsoleHelper.cut(service.getItemTitle(loan.getItemId()), 24),\n                    ConsoleHelper.cut(service.getMemberName(loan.getMemberId()), 18),\n                    ConsoleHelper.money(loan.getFineAmount()),\n                    loan.isFinePaid() ? \"Paid\" : \"UNPAID\");\n        }\n        console.info(\"Total unpaid fines: \" + ConsoleHelper.money(unpaidTotal));\n\n        if (unpaidTotal > 0 && console.readYesNo(\"Pay a fine now? (y/n): \")) {\n            String loanId = console.readText(\"Loan ID of the fine to pay: \");\n            try {\n                service.payFine(loanId);\n                console.success(\"The fine of loan \" + loanId.toUpperCase() + \" is marked as paid.\");\n                autoSave();\n            } catch (LibraryException e) {\n                console.error(e.getMessage());\n            }\n        }\n    }"},{"t":"viewNotifications (option 9)","n":"<p>Prints the notices saved in <code>notificationLog</code> for this session, numbered from 1.</p>","a":562,"c":"    /** Shows the notices that were sent during this session. */\n    private void viewNotifications() {\n        if (notificationLog.isEmpty()) {\n            console.info(\"There are no notifications in this session.\");\n            return;\n        }\n        console.blank();\n        console.line(\"--- Notifications (this session) ---\");\n        int number = 1;\n        for (String message : notificationLog) {\n            console.line(number + \". \" + message);\n            number++;\n        }\n    }\n}"}]}];
